('javascript','es6-plus','javascript-es6-plus-005','Array Destructuring','const [a, b] = array;','Unpacks values from an array into distinct variables based on position.',null,null,'const [first, second] = [1, 2, 3]; // first = 1, second = 2','javascript','Supports skipping elements ([, second]) and default values ([a = 10] = []).',ARRAY['javascript','es6','destructuring']::text[],5),
('javascript','es6-plus','javascript-es6-plus-006','Object Destructuring','const { key1, key2: alias } = obj;','Unpacks properties from an object into distinct variables based on property name, with optional renaming and defaults.',null,null,'const { name, age = 30 } = { name: ''Sam'' }; // name = ''Sam'', age = 30','javascript','Commonly used for destructuring function parameters, e.g. function greet({ name }) { ... }.',ARRAY['javascript','es6','destructuring']::text[],6),
