('javascript','es6-plus','javascript-es6-plus-008','Rest Parameters','function fn(a, b, ...rest) { ... }','Collects all remaining arguments passed to a function into a real array, instead of using the array-like `arguments` object.',null,null,'function sum(...nums) { return nums.reduce((a, b) => a + b, 0); } sum(1, 2, 3); // 6','javascript','Must be the last parameter in the function signature; also works in destructuring, e.g. const [first, ...others] = arr.',ARRAY['javascript','es6','functions']::text[],8),
('javascript','es6-plus','javascript-es6-plus-009','Default Parameters','function fn(param = defaultValue) { ... }','Allows named parameters to be initialized with default values if no value or undefined is passed.',null,null,'function greet(name = ''Guest'') { return `Hi, ${name}`; } greet(); // ''Hi, Guest''','javascript','Default values are evaluated at call time and can reference earlier parameters.',ARRAY['javascript','es6','functions']::text[],9),
('javascript','es6-plus','javascript-es6-plus-010','Classes','class Name { constructor(...) { ... } method() { ... } }','Syntactic sugar over JavaScript''s prototype-based inheritance, providing a cleaner syntax for creating objects and handling inheritance.',null,null,'class Point { constructor(x, y) { this.x = x; this.y = y; } }','javascript','Class declarations are not hoisted the way function declarations are — they exist in the temporal dead zone until evaluated.',ARRAY['javascript','es6','classes']::text[],10),
('javascript','es6-plus','javascript-es6-plus-011','Class Inheritance (extends/super)','class Child extends Parent { constructor() { super(); } }','Lets one class inherit properties and methods from another using extends, with super() used to call the parent constructor.',null,null,'class Animal { speak() { return ''sound''; } } class Dog extends Animal { speak() { return ''bark''; } }','javascript','super() must be called before `this` can be used in a subclass constructor.',ARRAY['javascript','es6','classes']::text[],11),
