('javascript','es6-plus','javascript-es6-plus-013','Optional Chaining (?.)','obj?.prop / obj?.[key] / obj?.method?.()','Accesses a deeply nested property without throwing an error if an intermediate property is null or undefined.',null,null,'const city = user?.address?.city; // undefined instead of throwing, if address is missing','javascript','Short-circuits and returns undefined as soon as it hits a nullish value, without evaluating the rest of the chain.',ARRAY['javascript','es6','operators']::text[],13),
('javascript','es6-plus','javascript-es6-plus-014','Nullish Coalescing (??)','value ?? defaultValue','Returns the right-hand operand only when the left-hand operand is null or undefined, unlike || which also treats 0, '''', and false as absent.',null,null,'const count = 0 ?? 5; // 0 (|| would incorrectly give 5)','javascript','Cannot be directly combined with && or || without parentheses due to operator precedence rules.',ARRAY['javascript','es6','operators']::text[],14),
('javascript','es6-plus','javascript-es6-plus-015','Map','new Map([[key1, value1], [key2, value2]])','A collection of key-value pairs where keys can be of any type (including objects), and insertion order is preserved.',null,null,'const m = new Map(); m.set(''a'', 1); m.get(''a''); // 1','javascript','Unlike plain objects, Map keys aren''t coerced to strings and Map has a built-in .size property.',ARRAY['javascript','es6','data-structures']::text[],15),
