('javascript','es6-plus','javascript-es6-plus-018','Generator Functions','function* gen() { yield value; }','Functions that can be paused and resumed, producing a sequence of values over multiple calls via the yield keyword.',null,null,'function* count() { yield 1; yield 2; } const it = count(); it.next(); // { value: 1, done: false }','javascript','Generators return an iterator, making them useful for lazy sequences and custom iteration protocols.',ARRAY['javascript','es6','iterators']::text[],18),
('javascript','es6-plus','javascript-es6-plus-019','Computed Property Names','const obj = { [expression]: value };','Allows an object property''s key to be computed dynamically from an expression at object-literal creation time.',null,null,'const key = ''name''; const obj = { [key]: ''Sam'' }; // { name: ''Sam'' }','javascript',null,ARRAY['javascript','es6','objects']::text[],19),
('javascript','es6-plus','javascript-es6-plus-020','Shorthand Property Names','const obj = { name, age };','Lets you create an object property using a variable''s name as the key and its value as the property value, without repeating the name.',null,null,'const name = ''Sam''; const age = 30; const person = { name, age }; // { name: ''Sam'', age: 30 }','javascript','Also applies to method definitions: { greet() { ... } } instead of { greet: function() { ... } }.',ARRAY['javascript','es6','objects']::text[],20),
('javascript','functions','javascript-functions-001','Function Declaration','function name(param1, param2) { ... }','Defines a named function using the function keyword. Function declarations are hoisted, so they can be called before their definition in the code.',null,null,'greet(''Sam''); function greet(name) { console.log(`Hi, ${name}`); }','javascript','Fully hoisted, including the function body — unlike function expressions.',ARRAY['javascript','functions','declarations']::text[],1),
('javascript','functions','javascript-functions-002','Function Expression','const name = function(param1, param2) { ... };','Defines a function as part of an expression, typically assigned to a variable. Not hoisted the way declarations are.',null,null,'const greet = function(name) { return `Hi, ${name}`; };','javascript','Can be named or anonymous; a named function expression''s name is only visible inside its own body.',ARRAY['javascript','functions','declarations']::text[],2),
('javascript','functions','javascript-functions-003','Closures',null,'A closure is formed when an inner function retains access to variables from its enclosing (outer) function''s scope, even after the outer function has returned.',null,null,'function counter() { let count = 0; return () => ++count; } const inc = counter(); inc(); // 1','javascript','Closures are the mechanism behind private state, memoization, and function factories in JavaScript.',ARRAY['javascript','functions','scope']::text[],3),
('javascript','functions','javascript-functions-004','IIFE (Immediately Invoked Function Expression)','(function() { ... })();','A function that is defined and executed immediately after creation, commonly used to create an isolated scope.',null,null,'(function() { console.log(''runs immediately''); })();','javascript','Largely superseded by block scoping (let/const) and ES modules, which provide scope isolation without the IIFE pattern.',ARRAY['javascript','functions','scope']::text[],4),
('javascript','functions','javascript-functions-005','Higher-Order Functions',null,'A function that either accepts one or more functions as arguments, returns a function, or both.',null,null,'function withLogging(fn) { return (...args) => { console.log(''calling''); return fn(...args); }; }','javascript','Array methods like map(), filter(), and reduce() are all higher-order functions since they accept a callback.',ARRAY['javascript','functions','patterns']::text[],5),
('javascript','functions','javascript-functions-006','this Keyword','this','Refers to the context in which a function is called. Its value depends on how the function is invoked — as a method, a plain function, a constructor, or via call/apply/bind.',null,null,'const obj = { name: ''Sam'', greet() { return this.name; } }; obj.greet(); // ''Sam''','javascript','Arrow functions do not have their own `this` — they inherit it lexically from the enclosing scope.',ARRAY['javascript','functions','this']::text[],6),
('javascript','functions','javascript-functions-007','call()','fn.call(thisArg, arg1, arg2, ...)','Invokes a function immediately with a specified `this` value and arguments passed individually.','thisArg — value to use as `this`. arg1, arg2, ... — arguments passed to the function.','The return value of the called function.','function greet() { return `Hi, ${this.name}`; } greet.call({ name: ''Sam'' }); // ''Hi, Sam''','javascript',null,ARRAY['javascript','functions','this']::text[],7),
('javascript','functions','javascript-functions-008','apply()','fn.apply(thisArg, [argsArray])','Invokes a function immediately with a specified `this` value and arguments provided as an array.','thisArg — value to use as `this`. argsArray — array (or array-like) of arguments to pass.','The return value of the called function.','function sum(a, b) { return a + b; } sum.apply(null, [1, 2]); // 3','javascript','Functionally identical to call(), differing only in how arguments are supplied — the spread operator has made apply() less common.',ARRAY['javascript','functions','this']::text[],8),
('javascript','functions','javascript-functions-009','bind()','const boundFn = fn.bind(thisArg, arg1, arg2, ...)','Returns a new function with `this` permanently bound to the given value, optionally pre-filling some arguments.','thisArg — value to bind as `this`. arg1, arg2, ... — optional arguments to pre-bind (partial application).','A new function with bound context (and arguments, if provided).','const greet = function() { return this.name; }.bind({ name: ''Sam'' }); greet(); // ''Sam''','javascript','Unlike call() and apply(), bind() does not invoke the function immediately — it returns a new one for later use.',ARRAY['javascript','functions','this']::text[],9),
('javascript','functions','javascript-functions-010','Recursion',null,'A technique where a function calls itself to solve a problem by breaking it into smaller subproblems, until reaching a base case.',null,null,'function factorial(n) { return n <= 1 ? 1 : n * factorial(n - 1); } factorial(5); // 120','javascript','Without a well-defined base case, recursion causes a "Maximum call stack size exceeded" error.',ARRAY['javascript','functions','recursion']::text[],10),
('javascript','functions','javascript-functions-011','Pure Functions',null,'A function that always returns the same output for the same input and produces no side effects, such as mutating external state.',null,null,'const add = (a, b) => a + b; // pure — depends only on its arguments','javascript','Pure functions are easier to test, reason about, and are foundational to predictable state management patterns.',ARRAY['javascript','functions','patterns']::text[],11),
('javascript','functions','javascript-functions-012','Function Hoisting',null,'Function declarations are moved to the top of their containing scope during compilation, making them callable before their textual definition.',null,null,'sayHi(); function sayHi() { console.log(''hi''); } // works fine','javascript','Function expressions and arrow functions assigned to let/const are not hoisted this way — only the variable declaration is hoisted, not its value.',ARRAY['javascript','functions','hoisting']::text[],12),
('javascript','loops','javascript-loops-001','for Loop','for (initialization; condition; increment) { ... }','Repeats a block of code a set number of times, controlled by an initializer, a condition, and an increment expression.',null,null,'for (let i = 0; i < 3; i++) { console.log(i); } // 0, 1, 2','javascript','Best suited when you need index access or a fixed iteration count.',ARRAY['javascript','loops','iteration']::text[],1),
('javascript','loops','javascript-loops-002','for...in Loop','for (const key in obj) { ... }','Iterates over the enumerable property names (keys) of an object, including inherited enumerable properties.',null,null,'for (const key in { a: 1, b: 2 }) { console.log(key); } // ''a'', ''b''','javascript','Intended for object keys, not arrays — for arrays use for...of or forEach() to avoid iterating inherited/indexed quirks.',ARRAY['javascript','loops','object']::text[],2),
('javascript','loops','javascript-loops-003','for...of Loop','for (const item of iterable) { ... }','Iterates over the values of any iterable object, such as arrays, strings, Maps, and Sets.',null,null,'for (const value of [10, 20, 30]) { console.log(value); } // 10, 20, 30','javascript','Cannot be used directly on plain objects since they are not iterable — use Object.entries() with it instead.',ARRAY['javascript','loops','iteration']::text[],3),
('javascript','loops','javascript-loops-004','while Loop','while (condition) { ... }','Repeats a block of code as long as a specified condition evaluates to true, checked before each iteration.',null,null,'let i = 0; while (i < 3) { console.log(i); i++; }','javascript','If the condition never becomes false, the loop runs forever — ensure the loop body updates the condition.',ARRAY['javascript','loops','iteration']::text[],4),
('javascript','loops','javascript-loops-005','do...while Loop','do { ... } while (condition);','Repeats a block of code once before testing the condition, then continues while the condition remains true.',null,null,'let i = 0; do { console.log(i); i++; } while (i < 3);','javascript','Guarantees the loop body executes at least once, even if the condition is initially false.',ARRAY['javascript','loops','iteration']::text[],5),
('javascript','loops','javascript-loops-006','break Statement','break;','Immediately terminates the nearest enclosing loop or switch statement, resuming execution after it.',null,null,'for (let i = 0; i < 10; i++) { if (i === 3) break; console.log(i); } // 0, 1, 2','javascript','Can also be combined with a label to break out of an outer loop from within a nested one.',ARRAY['javascript','loops','control-flow']::text[],6),
('javascript','loops','javascript-loops-007','continue Statement','continue;','Skips the rest of the current loop iteration and proceeds to the next one.',null,null,'for (let i = 0; i < 5; i++) { if (i % 2 === 0) continue; console.log(i); } // 1, 3','javascript',null,ARRAY['javascript','loops','control-flow']::text[],7),
('javascript','loops','javascript-loops-008','Labeled Statements','outer: for (...) { for (...) { break outer; } }','A label identifies a loop so that break or continue can target it directly, even from inside a nested loop.',null,null,'outer: for (let i = 0; i < 3; i++) { for (let j = 0; j < 3; j++) { if (j === 1) continue outer; console.log(i, j); } }','javascript','Useful for breaking or continuing an outer loop from deeply nested loops, but overuse can hurt readability.',ARRAY['javascript','loops','control-flow']::text[],8),
('javascript','object-methods','javascript-object-methods-001','Object.keys()','Object.keys(obj)','Returns an array of a given object''s own enumerable property names, in the same order as a for...in loop.','obj — the object whose keys are to be returned.','An array of strings representing the object''s own enumerable keys.','Object.keys({ a: 1, b: 2 }); // [''a'', ''b'']','javascript','Does not include inherited or non-enumerable properties.',ARRAY['javascript','object','iteration']::text[],1),
('javascript','object-methods','javascript-object-methods-002','Object.values()','Object.values(obj)','Returns an array of a given object''s own enumerable property values.','obj — the object whose values are to be returned.','An array of the object''s own enumerable values, in the same order as Object.keys().','Object.values({ a: 1, b: 2 }); // [1, 2]','javascript',null,ARRAY['javascript','object','iteration']::text[],2),
('javascript','object-methods','javascript-object-methods-003','Object.entries()','Object.entries(obj)','Returns an array of a given object''s own enumerable [key, value] pairs.','obj — the object to convert.','An array of [key, value] pair arrays.','Object.entries({ a: 1, b: 2 }); // [[''a'', 1], [''b'', 2]]','javascript','Commonly paired with destructuring in a for...of loop: for (const [k, v] of Object.entries(obj))',ARRAY['javascript','object','iteration']::text[],3),
('javascript','object-methods','javascript-object-methods-004','Object.assign()','Object.assign(target, ...sources)','Copies all enumerable own properties from one or more source objects to a target object, mutating and returning the target.','target — object to copy properties into. sources — one or more objects to copy properties from.','The modified target object.','Object.assign({}, { a: 1 }, { b: 2 }); // { a: 1, b: 2 }','javascript','Performs a shallow copy — nested objects are still shared by reference. Passing {} as target avoids mutating a source object.',ARRAY['javascript','object','merging']::text[],4),
('javascript','object-methods','javascript-object-methods-005','Object.freeze()','Object.freeze(obj)','Freezes an object, preventing new properties from being added and existing ones from being removed or changed.','obj — the object to freeze.','The same object that was passed in, now frozen.','const o = Object.freeze({ a: 1 }); o.a = 2; // fails silently (throws in strict mode)','javascript','Freezing is shallow — nested objects inside a frozen object are not themselves frozen.',ARRAY['javascript','object','immutability']::text[],5),
('javascript','object-methods','javascript-object-methods-006','Object.isFrozen()','Object.isFrozen(obj)','Determines whether an object is frozen, meaning it is non-extensible and all its properties are non-configurable and non-writable.','obj — the object to check.','true if the object is frozen, otherwise false.','Object.isFrozen(Object.freeze({})); // true','javascript',null,ARRAY['javascript','object','immutability']::text[],6),
('javascript','object-methods','javascript-object-methods-007','Object.create()','Object.create(proto, propertiesObject)','Creates a new object using an existing object as the prototype of the newly created object.','proto — the object to use as the new object''s prototype. propertiesObject — optional property descriptors.','A new object with the specified prototype.','const proto = { greet() { return ''hi''; } }; const o = Object.create(proto); o.greet(); // ''hi''','javascript','Object.create(null) creates an object with no prototype at all, useful as a plain dictionary.',ARRAY['javascript','object','prototype']::text[],7),
('javascript','object-methods','javascript-object-methods-008','Object.getPrototypeOf()','Object.getPrototypeOf(obj)','Returns the prototype (internal [[Prototype]]) of the specified object.','obj — the object whose prototype to return.','The object''s prototype, or null if it has none.','Object.getPrototypeOf([]) === Array.prototype; // true','javascript',null,ARRAY['javascript','object','prototype']::text[],8),
('javascript','object-methods','javascript-object-methods-009','Object.setPrototypeOf()','Object.setPrototypeOf(obj, prototype)','Sets the prototype of a specified object to another object or null.','obj — the object to modify. prototype — the new prototype (an object or null).','The modified object.','const o = {}; Object.setPrototypeOf(o, { greet() { return ''hi''; } });','javascript','Changing the prototype after creation is slow — prefer Object.create() when possible.',ARRAY['javascript','object','prototype']::text[],9),
('javascript','object-methods','javascript-object-methods-010','hasOwnProperty()','obj.hasOwnProperty(prop)','Returns a boolean indicating whether the object has the specified property as its own (not inherited).','prop — the property name (string or symbol) to test.','true if the object directly owns the property, otherwise false.','({ a: 1 }).hasOwnProperty(''a''); // true','javascript','The safer Object.hasOwn(obj, prop) is now preferred since it works even on objects created with Object.create(null).',ARRAY['javascript','object','prototype']::text[],10),
('javascript','object-methods','javascript-object-methods-011','Object.defineProperty()','Object.defineProperty(obj, prop, descriptor)','Defines a new property directly on an object, or modifies an existing one, with fine-grained control via a descriptor.','obj — target object. prop — property name. descriptor — object describing value, writable, enumerable, configurable, or getter/setter.','The object that was passed to the function.','Object.defineProperty(obj, ''x'', { value: 1, writable: false });','javascript','Properties defined this way are non-enumerable by default, so they won''t show up in Object.keys() or for...in.',ARRAY['javascript','object','properties']::text[],11),
('javascript','object-methods','javascript-object-methods-012','Object.fromEntries()','Object.fromEntries(iterable)','Transforms a list of key-value pairs into an object, the inverse of Object.entries().','iterable — an iterable such as an array of [key, value] pairs, or a Map.','A new object built from the entries.','Object.fromEntries([[''a'', 1], [''b'', 2]]); // { a: 1, b: 2 }','javascript','Handy for converting a Map back into a plain object, or for transforming entries with map()/filter() before rebuilding.',ARRAY['javascript','object','conversion']::text[],12),
('javascript','object-methods','javascript-object-methods-013','Object.seal()','Object.seal(obj)','Seals an object, preventing new properties from being added but allowing existing writable properties to be changed.','obj — the object to seal.','The same object that was passed in, now sealed.','const o = Object.seal({ a: 1 }); o.a = 2; // allowed; o.b = 3; // ignored','javascript','Less restrictive than Object.freeze() — existing property values can still be reassigned.',ARRAY['javascript','object','immutability']::text[],13),
('javascript','object-methods','javascript-object-methods-014','Object.is()','Object.is(value1, value2)','Determines whether two values are the same value, using stricter semantics than === for edge cases like NaN and signed zero.','value1, value2 — the two values to compare.','true if the values are the same value, otherwise false.','Object.is(NaN, NaN); // true — unlike NaN === NaN which is false','javascript','Object.is(0, -0) returns false, whereas 0 === -0 returns true.',ARRAY['javascript','object','comparison']::text[],14),
('javascript','object-methods','javascript-object-methods-015','Object.getOwnPropertyNames()','Object.getOwnPropertyNames(obj)','Returns an array of all own property names of an object, including non-enumerable ones but excluding symbol keys.','obj — the object whose property names to return.','An array of strings representing all own property names.','Object.getOwnPropertyNames({ a: 1 }); // [''a'']','javascript','Unlike Object.keys(), this also includes non-enumerable properties.',ARRAY['javascript','object','properties']::text[],15),
('javascript','operators','javascript-operators-001','Arithmetic Operators','+  -  *  /  %  **','Perform mathematical calculations: addition, subtraction, multiplication, division, remainder (modulo), and exponentiation.',null,null,'10 % 3; // 1
2 ** 3; // 8','javascript','The + operator also performs string concatenation when either operand is a string.',ARRAY['javascript','operators','arithmetic']::text[],1),
('javascript','operators','javascript-operators-002','Assignment Operators','=  +=  -=  *=  /=  %=  **=','Assign a value to a variable, optionally combining the assignment with an arithmetic operation on the current value.',null,null,'let x = 5; x += 3; // x is 8','javascript',null,ARRAY['javascript','operators','assignment']::text[],2),
('javascript','operators','javascript-operators-003','Comparison Operators (== vs ===)','==  !=  ===  !==  <  >  <=  >=','Compare two values. == and != coerce types before comparing, while === and !== check both value and type without coercion.',null,null,'1 == ''1''; // true
1 === ''1''; // false','javascript','Best practice is to always use === and !== to avoid unpredictable coercion bugs.',ARRAY['javascript','operators','comparison']::text[],3),
('javascript','operators','javascript-operators-004','Logical Operators (&&, ||, !)','a && b   a || b   !a','Combine or invert boolean expressions. && returns the first falsy value (or the last value), || returns the first truthy value, ! inverts truthiness.',null,null,'true && ''yes''; // ''yes''
false || ''default''; // ''default''','javascript','&& and || are often used for short-circuit patterns like isReady && doThing() instead of an if statement.',ARRAY['javascript','operators','logical']::text[],4),
('javascript','operators','javascript-operators-005','Ternary Operator (?:)','condition ? valueIfTrue : valueIfFalse','A shorthand conditional expression that evaluates to one of two values depending on a condition.',null,null,'const status = age >= 18 ? ''adult'' : ''minor'';','javascript','Can be chained, but nested ternaries quickly hurt readability — prefer if/else for complex branching.',ARRAY['javascript','operators','conditionals']::text[],5),
('javascript','operators','javascript-operators-006','typeof Operator','typeof value','Returns a string indicating the type of the operand, such as ''string'', ''number'', ''boolean'', ''undefined'', ''object'', or ''function''.',null,null,'typeof ''hi''; // ''string''
typeof undefined; // ''undefined''','javascript','typeof null is ''object'' and typeof [] is also ''object'' — use Array.isArray() to detect arrays specifically.',ARRAY['javascript','operators','type-checking']::text[],6),
('javascript','operators','javascript-operators-007','instanceof Operator','object instanceof Constructor','Tests whether the prototype of a constructor appears anywhere in an object''s prototype chain.',null,null,'[] instanceof Array; // true
[] instanceof Object; // true','javascript','Does not work reliably across different execution contexts (e.g. iframes), where each has its own global constructors.',ARRAY['javascript','operators','type-checking']::text[],7),
('javascript','operators','javascript-operators-008','Bitwise Operators','&  |  ^  ~  <<  >>  >>>','Perform operations on the individual bits of numbers: AND, OR, XOR, NOT, left shift, sign-propagating right shift, and zero-fill right shift.',null,null,'5 & 1; // 1
5 << 1; // 10','javascript','Numbers are converted to 32-bit integers before bitwise operations are applied.',ARRAY['javascript','operators','bitwise']::text[],8),
('javascript','operators','javascript-operators-009','Comma Operator','expr1, expr2, expr3','Evaluates each of its operands from left to right and returns the value of the last operand.',null,null,'let x = (1 + 1, 2 + 2); // x is 4','javascript','Rarely used outside of for loop headers, e.g. for (let i = 0, j = 10; i < j; i++, j--).',ARRAY['javascript','operators','expressions']::text[],9),
('javascript','operators','javascript-operators-010','Increment/Decrement Operators (++/--)','x++  ++x  x--  --x','Increase or decrease a numeric variable by one. The prefix form returns the updated value; the postfix form returns the original value.',null,null,'let x = 5; x++; // x is 6
let y = 5; console.log(y++); // logs 5, then y is 6','javascript',null,ARRAY['javascript','operators','arithmetic']::text[],10),
('javascript','operators','javascript-operators-011','Logical Assignment Operators (&&=, ||=, ??=)','a &&= b   a ||= b   a ??= b','Combine a logical operation with assignment, only assigning the right-hand value when the logical condition is met.',null,null,'let config = {}; config.timeout ??= 5000; // sets timeout only if it was null/undefined','javascript','Introduced in ES2021 as a concise alternative to patterns like a = a || b.',ARRAY['javascript','operators','assignment']::text[],11),
('javascript','operators','javascript-operators-012','in Operator','''key'' in object','Tests whether a specified property exists in an object or its prototype chain.',null,null,'''toString'' in {}; // true (inherited)
