('javascript','operators','javascript-operators-013','delete Operator','delete object.property','Removes a property from an object entirely, rather than just setting it to undefined.',null,null,'const obj = { a: 1 }; delete obj.a; ''a'' in obj; // false','javascript','Has no effect on variables or function declarations — it only removes object properties.',ARRAY['javascript','operators','objects']::text[],13),
('javascript','operators','javascript-operators-014','void Operator','void expression','Evaluates an expression and discards its return value, always resulting in undefined.',null,null,'void 0; // undefined','javascript','Historically used in href="javascript:void(0)" links to prevent navigation without producing a visible return value.',ARRAY['javascript','operators','expressions']::text[],14),
('javascript','operators','javascript-operators-015','Exponentiation Operator (**)','base ** exponent','Raises the first operand to the power of the second operand, equivalent to Math.pow().',null,null,'2 ** 10; // 1024','javascript','Right-associative: 2 ** 3 ** 2 evaluates as 2 ** (3 ** 2) = 512.',ARRAY['javascript','operators','arithmetic']::text[],15),
('javascript','other-methods','javascript-other-methods-001','JSON.stringify()','JSON.stringify(value, replacer, space)','Converts a JavaScript value into a JSON string, optionally filtering properties and pretty-printing with indentation.','value — the value to serialize. replacer — optional function or array to filter properties. space — optional indentation for pretty-printing.','A JSON-formatted string.','JSON.stringify({ a: 1, b: 2 }, null, 2);','javascript','Functions, undefined values, and symbols are silently dropped or omitted during serialization.',ARRAY['javascript','json','serialization']::text[],1),
('javascript','other-methods','javascript-other-methods-002','JSON.parse()','JSON.parse(text, reviver)','Parses a JSON string, constructing the JavaScript value or object it describes.','text — the JSON string to parse. reviver — optional function to transform parsed values.','The JavaScript value corresponding to the parsed JSON text.','JSON.parse(''{"a":1}''); // { a: 1 }','javascript','Throws a SyntaxError on malformed JSON — wrap in try...catch when parsing untrusted input.',ARRAY['javascript','json','serialization']::text[],2),
('javascript','other-methods','javascript-other-methods-003','Math.random()','Math.random()','Returns a pseudo-random floating-point number in the range [0, 1), including 0 but excluding 1.',null,'A random number between 0 (inclusive) and 1 (exclusive).','Math.floor(Math.random() * 10); // random integer 0-9','javascript','Not cryptographically secure — use the Web Crypto API''s crypto.getRandomValues() for security-sensitive randomness.',ARRAY['javascript','math','random']::text[],3),
('javascript','other-methods','javascript-other-methods-004','Math.floor()','Math.floor(number)','Rounds a number down to the nearest integer.','number — the value to round down.','The largest integer less than or equal to the given number.','Math.floor(4.7); // 4','javascript',null,ARRAY['javascript','math','rounding']::text[],4),
('javascript','other-methods','javascript-other-methods-005','Math.round()','Math.round(number)','Rounds a number to the nearest integer, rounding .5 values up.','number — the value to round.','The rounded integer.','Math.round(4.5); // 5
Math.round(4.4); // 4','javascript',null,ARRAY['javascript','math','rounding']::text[],5),
('javascript','other-methods','javascript-other-methods-006','Math.max()','Math.max(value1, value2, ...)','Returns the largest of the given numbers.','value1, value2, ... — numbers to compare.','The largest value, or -Infinity if no arguments are given.','Math.max(1, 5, 3); // 5
Math.max(...[1, 5, 3]); // 5','javascript','Use the spread operator to apply it to an array: Math.max(...array).',ARRAY['javascript','math']::text[],6),
('javascript','other-methods','javascript-other-methods-007','Math.min()','Math.min(value1, value2, ...)','Returns the smallest of the given numbers.','value1, value2, ... — numbers to compare.','The smallest value, or Infinity if no arguments are given.','Math.min(1, 5, 3); // 1','javascript',null,ARRAY['javascript','math']::text[],7),
('javascript','other-methods','javascript-other-methods-008','Math.abs()','Math.abs(number)','Returns the absolute (non-negative) value of a number.','number — the value to convert.','The absolute value.','Math.abs(-5); // 5','javascript',null,ARRAY['javascript','math']::text[],8),
('javascript','other-methods','javascript-other-methods-009','Number.isInteger()','Number.isInteger(value)','Determines whether the given value is an integer, without coercing the input type.','value — the value to test.','true if the value is a number and an integer, otherwise false.','Number.isInteger(5); // true
Number.isInteger(5.5); // false
Number.isInteger(''5''); // false','javascript','Unlike the global isInteger-style checks, this does not coerce strings — ''5'' is not considered an integer.',ARRAY['javascript','numbers','type-checking']::text[],9),
('javascript','other-methods','javascript-other-methods-010','Number.parseFloat()','Number.parseFloat(string)','Parses a string and returns a floating-point number, reading as much of the string as looks like a valid number.','string — the string to parse.','The parsed floating-point number, or NaN if the string cannot be parsed.','Number.parseFloat(''3.14abc''); // 3.14','javascript','Equivalent to the global parseFloat() function, but namespaced under Number for module-style consistency.',ARRAY['javascript','numbers','parsing']::text[],10),
('javascript','other-methods','javascript-other-methods-011','console.log()','console.log(value1, value2, ...)','Outputs one or more values to the console, commonly used for debugging.','value1, value2, ... — any values to print.',null,'console.log(''user:'', { name: ''Sam'' });','javascript','Supports string substitution with %s, %d, %o and CSS styling with %c.',ARRAY['javascript','console','debugging']::text[],11),
('javascript','other-methods','javascript-other-methods-012','console.table()','console.table(data)','Displays tabular data (an array of objects or a 2D structure) as a formatted table in the console.','data — an array or object to render as a table.',null,'console.table([{ id: 1, name: ''Sam'' }, { id: 2, name: ''Alex'' }]);','javascript','Much easier to scan than console.log() for arrays of similarly-shaped objects.',ARRAY['javascript','console','debugging']::text[],12),
('javascript','other-methods','javascript-other-methods-013','setTimeout()','setTimeout(callback, delayMs, ...args)','Schedules a function to run once after a specified delay, without blocking the rest of the program.','callback — function to execute. delayMs — delay in milliseconds. args — optional arguments passed to callback.','A timeout ID that can be passed to clearTimeout().','setTimeout(() => console.log(''later''), 1000);','javascript','The delay is a minimum, not a guarantee — actual execution can be delayed further by the event loop''s workload.',ARRAY['javascript','timers','async']::text[],13),
('javascript','other-methods','javascript-other-methods-014','setInterval()','setInterval(callback, intervalMs, ...args)','Repeatedly calls a function with a fixed time delay between each call, until cleared.','callback — function to execute repeatedly. intervalMs — delay between calls in milliseconds. args — optional arguments passed to callback.','An interval ID that can be passed to clearInterval().','const id = setInterval(() => console.log(''tick''), 1000);','javascript','Always store the returned ID so the interval can be stopped later — forgetting to clear it is a common source of memory leaks.',ARRAY['javascript','timers','async']::text[],14),
('javascript','other-methods','javascript-other-methods-015','clearTimeout()','clearTimeout(timeoutId)','Cancels a timeout previously scheduled with setTimeout(), preventing its callback from running.','timeoutId — the ID returned by setTimeout().',null,'const id = setTimeout(doThing, 5000); clearTimeout(id); // doThing never runs','javascript','Also works to cancel a setInterval() timer via its interval-ID counterpart, clearInterval().',ARRAY['javascript','timers','async']::text[],15),
('javascript','promises-async-await','javascript-promises-async-await-001','Promise Constructor','new Promise((resolve, reject) => { ... })','Creates a new Promise representing the eventual completion (or failure) of an asynchronous operation.','executor — function receiving resolve and reject callbacks, invoked immediately.','A new Promise object.','const p = new Promise((resolve, reject) => { setTimeout(() => resolve(''done''), 1000); });','javascript','The executor function runs synchronously as soon as the Promise is constructed.',ARRAY['javascript','promises','async']::text[],1),
('javascript','promises-async-await','javascript-promises-async-await-002','.then()','promise.then(onFulfilled, onRejected)','Registers callbacks to run when a Promise settles — one for fulfillment, an optional one for rejection.','onFulfilled — called with the resolved value. onRejected — optional, called with the rejection reason.','A new Promise, allowing .then() calls to be chained.','fetch(url).then(res => res.json()).then(data => console.log(data));','javascript','Each .then() returns a new Promise, so returning a value (or Promise) inside it flows into the next .then().',ARRAY['javascript','promises','async']::text[],2),
('javascript','promises-async-await','javascript-promises-async-await-003','.catch()','promise.catch(onRejected)','Registers a callback to handle rejection anywhere earlier in the Promise chain — shorthand for .then(undefined, onRejected).','onRejected — function called with the rejection reason.','A new Promise.','fetch(url).then(res => res.json()).catch(err => console.error(err));','javascript','A single .catch() at the end of a chain will catch errors from any preceding .then() in that chain.',ARRAY['javascript','promises','error-handling']::text[],3),
('javascript','promises-async-await','javascript-promises-async-await-004','.finally()','promise.finally(onFinally)','Registers a callback that runs when the Promise settles, regardless of whether it was fulfilled or rejected.','onFinally — function called with no arguments once the promise settles.','A new Promise that resolves/rejects with the same outcome as the original.','fetchData().finally(() => setLoading(false));','javascript','Commonly used to stop loading spinners or clean up resources regardless of success or failure.',ARRAY['javascript','promises','async']::text[],4),
('javascript','promises-async-await','javascript-promises-async-await-005','async Function','async function fn() { ... }','Declares a function that implicitly returns a Promise and allows the use of await inside its body.',null,null,'async function getData() { return 42; } getData().then(v => console.log(v)); // 42','javascript','Any value returned from an async function is automatically wrapped in a resolved Promise; thrown errors become rejected Promises.',ARRAY['javascript','async-await','async']::text[],5),
('javascript','promises-async-await','javascript-promises-async-await-006','await Keyword','const result = await promise;','Pauses execution of an async function until the given Promise settles, then returns its resolved value or throws its rejection.',null,null,'async function load() { const res = await fetch(url); const data = await res.json(); return data; }','javascript','Can only be used inside an async function (or at the top level of a module).',ARRAY['javascript','async-await','async']::text[],6),
('javascript','promises-async-await','javascript-promises-async-await-007','Promise.all()','Promise.all([p1, p2, p3])','Runs multiple Promises concurrently and resolves once all of them fulfill, or rejects immediately if any one rejects.','An iterable of Promises.','A Promise that resolves to an array of results, in the same order as the input.','const [users, posts] = await Promise.all([fetchUsers(), fetchPosts()]);','javascript','Fails fast — one rejected Promise causes the entire Promise.all() to reject, even if others would have succeeded.',ARRAY['javascript','promises','concurrency']::text[],7),
('javascript','promises-async-await','javascript-promises-async-await-008','Promise.race()','Promise.race([p1, p2, p3])','Returns a Promise that settles as soon as the first of the given Promises settles, whether fulfilled or rejected.','An iterable of Promises.','A Promise matching the outcome of whichever input settles first.','Promise.race([fetchData(), timeout(5000)]); // whichever finishes first wins','javascript','Commonly used to implement request timeouts by racing a fetch against a rejecting timer Promise.',ARRAY['javascript','promises','concurrency']::text[],8),
('javascript','promises-async-await','javascript-promises-async-await-009','Promise.allSettled()','Promise.allSettled([p1, p2, p3])','Runs multiple Promises concurrently and waits for all of them to settle, regardless of whether they fulfill or reject.','An iterable of Promises.','A Promise resolving to an array of { status, value } or { status, reason } objects for each input.','const results = await Promise.allSettled([ok(), fail()]); // [{status:''fulfilled'',...}, {status:''rejected'',...}]','javascript','Unlike Promise.all(), it never short-circuits on rejection — useful when you need every result regardless of failures.',ARRAY['javascript','promises','concurrency']::text[],9),
('javascript','promises-async-await','javascript-promises-async-await-010','Promise.any()','Promise.any([p1, p2, p3])','Resolves as soon as any one of the given Promises fulfills; only rejects if all of them reject.','An iterable of Promises.','A Promise that resolves with the first fulfilled value, or rejects with an AggregateError if all reject.','const first = await Promise.any([mirrorA(), mirrorB(), mirrorC()]);','javascript','Useful for querying redundant sources and using whichever responds successfully first.',ARRAY['javascript','promises','concurrency']::text[],10),
('javascript','promises-async-await','javascript-promises-async-await-011','Promise.resolve()','Promise.resolve(value)','Returns a Promise that is already resolved with the given value.','value — the value (or thenable) to resolve with.','A resolved Promise.','Promise.resolve(5).then(v => console.log(v)); // 5','javascript','Useful for normalizing a value that might or might not already be a Promise.',ARRAY['javascript','promises','async']::text[],11),
('javascript','promises-async-await','javascript-promises-async-await-012','Promise.reject()','Promise.reject(reason)','Returns a Promise that is already rejected with the given reason.','reason — the value (typically an Error) used as the rejection reason.','A rejected Promise.','Promise.reject(new Error(''failed'')).catch(err => console.log(err.message));','javascript',null,ARRAY['javascript','promises','async']::text[],12),
('javascript','promises-async-await','javascript-promises-async-await-013','try...catch with async/await','try { await fn(); } catch (err) { ... }','Wraps awaited code in a try...catch block to handle rejected Promises with the same syntax used for synchronous errors.',null,null,'async function load() { try { const data = await fetchData(); return data; } catch (err) { console.error(err); } }','javascript','Without a try...catch (or a .catch() on the call site), a rejected awaited Promise throws an unhandled rejection.',ARRAY['javascript','async-await','error-handling']::text[],13),
('javascript','promises-async-await','javascript-promises-async-await-014','Error Handling in Promise Chains',null,'Errors thrown anywhere inside a .then() callback, or a rejected Promise anywhere upstream, propagate down the chain to the nearest .catch().',null,null,'doStep1().then(doStep2).then(doStep3).catch(err => console.error(''chain failed:'', err));','javascript','A single .catch() at the end is usually sufficient — no need to add one after every .then().',ARRAY['javascript','promises','error-handling']::text[],14),
('javascript','promises-async-await','javascript-promises-async-await-015','Promise States (pending/fulfilled/rejected)',null,'A Promise is always in one of three states: pending (initial, not yet settled), fulfilled (operation succeeded), or rejected (operation failed). Once settled, its state and value never change.',null,null,'const p = new Promise(resolve => resolve(1)); // fulfilled with value 1','javascript','A settled Promise''s outcome is immutable — calling resolve() or reject() again after settling has no effect.',ARRAY['javascript','promises','concepts']::text[],15),
('javascript','string-methods','javascript-string-methods-001','charAt()','string.charAt(index)','Returns the character at the specified index in a string.','index — zero-based position of the character to return (default 0).','A single-character string, or an empty string if the index is out of range.','''hello''.charAt(1); // ''e''','javascript','Bracket notation (''hello''[1]) does the same thing and is more commonly used today.',ARRAY['javascript','string','access']::text[],1),
('javascript','string-methods','javascript-string-methods-002','charCodeAt()','string.charCodeAt(index)','Returns the UTF-16 numeric code of the character at the given index.','index — zero-based position of the character (default 0).','A number representing the UTF-16 code unit, or NaN if out of range.','''A''.charCodeAt(0); // 65','javascript','Use String.fromCharCode() to go the other direction, from code to character.',ARRAY['javascript','string','unicode']::text[],2),
('javascript','string-methods','javascript-string-methods-003','String.at()','string.at(index)','Returns the character at the given index, supporting negative indices to count from the end of the string.','index — position to access; negative values count backward from the end.','A single-character string, or undefined if out of range.','''hello''.at(-1); // ''o''','javascript','Also available on arrays as array.at(index).',ARRAY['javascript','string','access']::text[],3),
('javascript','string-methods','javascript-string-methods-004','String.indexOf()','string.indexOf(searchValue, fromIndex)','Returns the index of the first occurrence of a substring within the string, or -1 if not found.','searchValue — substring to search for. fromIndex — optional index to start searching from.','The index of the first match, or -1.','''hello world''.indexOf(''world''); // 6','javascript',null,ARRAY['javascript','string','search']::text[],4),
('javascript','string-methods','javascript-string-methods-005','String.lastIndexOf()','string.lastIndexOf(searchValue, fromIndex)','Returns the index of the last occurrence of a substring, searching the string backwards.','searchValue — substring to search for. fromIndex — optional index to start searching backward from.','The index of the last match, or -1 if not found.','''a-b-a''.lastIndexOf(''a''); // 4','javascript',null,ARRAY['javascript','string','search']::text[],5),
('javascript','string-methods','javascript-string-methods-006','String.includes()','string.includes(searchValue, fromIndex)','Determines whether one string may be found within another, returning true or false.','searchValue — substring to search for. fromIndex — optional index to start searching from.','Boolean indicating whether the substring was found.','''hello world''.includes(''wor''); // true','javascript','Case-sensitive — normalize casing with toLowerCase() first if needed.',ARRAY['javascript','string','search']::text[],6),
