('javascript','string-methods','javascript-string-methods-008','endsWith()','string.endsWith(searchValue, endPosition)','Determines whether a string ends with the characters of a specified substring.','searchValue — substring to check for. endPosition — optional index treated as the end of the string.','Boolean indicating whether the string ends with searchValue.','''file.txt''.endsWith(''.txt''); // true','javascript',null,ARRAY['javascript','string','search']::text[],8),
('javascript','string-methods','javascript-string-methods-009','String.slice()','string.slice(start, end)','Extracts a section of a string and returns it as a new string, without modifying the original.','start — index to begin extraction. end — index to stop before (exclusive).','A new string containing the extracted section.','''hello world''.slice(0, 5); // ''hello''','javascript','Supports negative indices, which count from the end of the string — unlike substring().',ARRAY['javascript','string','extraction']::text[],9),
('javascript','string-methods','javascript-string-methods-010','substring()','string.substring(start, end)','Returns the part of the string between two indices, similar to slice() but without negative index support.','start — index to begin extraction. end — index to stop before (exclusive).','A new string containing the extracted section.','''hello world''.substring(6, 11); // ''world''','javascript','Negative or swapped arguments are automatically clamped/swapped, unlike slice().',ARRAY['javascript','string','extraction']::text[],10),
('javascript','string-methods','javascript-string-methods-011','split()','string.split(separator, limit)','Splits a string into an array of substrings based on a specified separator.','separator — string or regex to split on. limit — optional maximum number of pieces to include.','An array of substrings.','''a,b,c''.split('',''); // [''a'', ''b'', ''c'']','javascript','Passing an empty string splits into individual characters.',ARRAY['javascript','string','conversion']::text[],11),
