('javascript','string-methods','javascript-string-methods-017','replace()','string.replace(pattern, replacement)','Returns a new string with the first match of a pattern replaced by a given replacement.','pattern — string or regex to match. replacement — string or function producing the replacement.','A new string with the replacement applied.','''2024-01-01''.replace(''-'', ''/''); // ''2024/01-01''','javascript','Only replaces the first match unless a global regex (/pattern/g) is used.',ARRAY['javascript','string','formatting']::text[],17),
('javascript','string-methods','javascript-string-methods-018','replaceAll()','string.replaceAll(pattern, replacement)','Returns a new string with all matches of a pattern replaced by a given replacement.','pattern — string or global regex to match. replacement — string or function producing the replacement.','A new string with all replacements applied.','''2024-01-01''.replaceAll(''-'', ''/''); // ''2024/01/01''','javascript','A non-global regex pattern throws a TypeError — use the /g flag or a string pattern.',ARRAY['javascript','string','formatting']::text[],18),
('javascript','string-methods','javascript-string-methods-019','repeat()','string.repeat(count)','Constructs and returns a new string containing the specified number of copies of the original string.','count — number of times to repeat, must be a non-negative integer.','A new, repeated string.','''ab''.repeat(3); // ''ababab''','javascript','Throws a RangeError for negative or infinite counts.',ARRAY['javascript','string','formatting']::text[],19),
('javascript','string-methods','javascript-string-methods-020','padStart()','string.padStart(targetLength, padString)','Pads the current string from the start with a given string until it reaches the target length.','targetLength — desired total length. padString — string to pad with (default is a space).','A new, padded string.','''5''.padStart(3, ''0''); // ''005''','javascript','Commonly used for zero-padding numbers or aligning output.',ARRAY['javascript','string','formatting']::text[],20),
