('html','attributes','html-attributes-015','hidden','<div hidden>','Hides an element from rendering entirely, equivalent to display: none, without removing it from the DOM.',null,null,'<p hidden>This paragraph is not shown.</p>','html','A boolean attribute; toggle it via JavaScript (el.hidden = true) to show/hide content.',ARRAY['html','attribute','css']::text[],15),
('html','attributes','html-attributes-016','draggable','<div draggable="true">','Marks whether an element can be dragged using the native HTML Drag and Drop API.',null,null,'<div draggable="true" ondragstart="handleDrag(event)">Drag me</div>','html','Most elements aren''t draggable by default; images and links are exceptions.',ARRAY['html','attribute','javascript']::text[],16),
