('css','grid','css-grid-014','auto-fit vs auto-fill','repeat(auto-fit | auto-fill, minmax(min, max))','Automatically determines how many tracks fit in the container; auto-fit collapses empty tracks to zero width while auto-fill preserves their space.',null,null,'.gallery {
