('css','other-features','css-other-features-005','Specificity',null,'The algorithm browsers use to decide which CSS rule wins when multiple rules target the same element, ranked roughly as inline styles > IDs > classes/attributes/pseudo-classes > element type selectors.',null,null,'#nav .link { color: red; } /* wins over */ .link { color: blue; }','css','!important and inline styles override normal specificity rules entirely, which is why overusing them makes CSS hard to maintain.',ARRAY['css','concepts','specificity']::text[],5),
('css','other-features','css-other-features-006','Cascade',null,'The process by which browsers combine multiple CSS sources — origin (browser/author/user), specificity, and source order — to determine the final value of each property.',null,null,null,null,'When specificity is equal, the rule declared later in the source order wins.',ARRAY['css','concepts','cascade']::text[],6),
('css','other-features','css-other-features-007','Inheritance',null,'Certain CSS properties, mostly text-related ones like color and font-family, are automatically passed down from a parent element to its children unless explicitly overridden.',null,null,'body {
  font-family: sans-serif;
} /* inherited by all descendant text */','css','Layout properties like margin, padding, and border do not inherit by default; the inherit keyword can force any property to inherit explicitly.',ARRAY['css','concepts','inheritance']::text[],7),
('css','other-features','css-other-features-008','Box model',null,'The model describing how an element''s total rendered size is composed of its content, padding, border, and margin layers.',null,null,null,null,'By default (content-box), width/height apply only to the content area — box-sizing: border-box makes them include padding and border instead.',ARRAY['css','concepts','box-model']::text[],8),
('css','other-features','css-other-features-009','CSS units (absolute vs relative)',null,'CSS supports absolute units like px, which are fixed regardless of context, and relative units like %, em, rem, vw, and vh, which scale based on another value such as the parent, root, or viewport.',null,null,null,null,'Relative units are generally preferred for responsive, accessible layouts since they scale with user font-size preferences and viewport changes.',ARRAY['css','concepts','units']::text[],9),
('css','other-features','css-other-features-010','!important','property: value !important;','Forces a declaration to override any other declaration for the same property, regardless of normal specificity rules.',null,null,'.alert {
  color: red !important;
}','css','Generally considered a last resort — overusing it makes styles hard to override and debug later.',ARRAY['css','concepts','specificity']::text[],10),
('css','other-features','css-other-features-011','CSS reset / normalize',null,'A base stylesheet applied first that removes or normalizes inconsistent default browser styling (margins, list bullets, font sizing) so components render predictably across browsers.',null,null,'* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
