('react','hooks','react-hooks-009','Custom Hooks','function useCustomThing() { /* uses other hooks */ return value; }','A JavaScript function whose name starts with `use` and that calls other Hooks internally, letting you extract and reuse stateful logic across components.',null,'Whatever the custom hook chooses to return — state, functions, derived values, etc.','function useWindowWidth() {
