  props.value = 0; // never do this
  return <span>{props.value}</span>;
}','jsx','If a child needs to change data owned by a parent, the parent should pass a callback prop instead of letting the child mutate props directly.',ARRAY['react','props','immutability']::text[],7),
('react','props','react-props-008','PropTypes','MyComponent.propTypes = { name: PropTypes.string.isRequired };','A runtime type-checking library for React props, from the separate `prop-types` package, used mainly in JavaScript (non-TypeScript) codebases.',null,null,'import PropTypes from ''prop-types'';

function Avatar({ src, size }) {
  return <img src={src} width={size} height={size} />;
}

Avatar.propTypes = {
  src: PropTypes.string.isRequired,
  size: PropTypes.number,
};','jsx','Only warns in development via the console; TypeScript is generally preferred for compile-time prop checking in new projects.',ARRAY['react','props','validation']::text[],8),
('react','state','react-state-001','State',null,'Data that a component owns and manages internally, which can change over time and causes the component to re-render when updated.',null,null,null,'jsx','Unlike props, state is local to the component and controlled by that component (or lifted to a parent), not passed in from outside.',ARRAY['react','state','fundamentals']::text[],1),
('react','state','react-state-002','Lifting State Up',null,'Moving shared state to the closest common ancestor of the components that need it, then passing it back down via props, so multiple components stay in sync.',null,null,'function Parent() {
  const [value, setValue] = useState('''');
  return (
    <>
      <InputA value={value} onChange={setValue} />
      <InputB value={value} onChange={setValue} />
    </>
  );
}','jsx',null,ARRAY['react','state','patterns']::text[],2),
('react','state','react-state-003','State vs Props',null,'Props are passed in from a parent and are read-only from the receiving component''s perspective; state is owned and can be updated by the component itself.',null,null,null,'jsx','A component re-renders when either its own state changes or the props it receives change.',ARRAY['react','state','props']::text[],3),
('react','state','react-state-004','Immutability of State','setItems([...items, newItem]); // not items.push(newItem)','State must be updated by creating a new value (new object/array) rather than mutating the existing one in place, so React can detect the change and re-render.',null,null,'setUser(prev => ({ ...prev, name: ''New Name'' }));
setList(prev => [...prev, newItem]);','jsx','Mutating state directly (e.g. `arr.push()`, `obj.prop = x`) can silently fail to trigger a re-render because React compares references, not deep equality.',ARRAY['react','state','immutability']::text[],4),
('react','state','react-state-005','Batched State Updates',null,'React groups multiple `setState` calls triggered within the same event handler (and, since React 18, in most other contexts too) into a single re-render for performance.',null,null,'function handleClick() {
  setCount(c => c + 1);
  setFlag(f => !f);
  // both updates applied, only one re-render
}','jsx','Use the functional updater form (`setCount(c => c + 1)`) when a new value depends on the previous one, since batched updates can make reading the outer variable stale.',ARRAY['react','state','performance']::text[],5),
('react','state','react-state-006','Derived State Anti-Pattern',null,'Storing a value in state that could instead be computed directly from existing props/state during render, which leads to state going out of sync with its source.',null,null,'// avoid:
const [fullName, setFullName] = useState(first + '' '' + last);
// prefer:
const fullName = first + '' '' + last;','jsx','If a value can be calculated from props/state during render, compute it inline (or with useMemo for expensive calculations) instead of duplicating it into its own state.',ARRAY['react','state','anti-pattern']::text[],6),
('react','state','react-state-007','Lazy Initial State','const [state, setState] = useState(() => computeInitial());','Passing a function to `useState` so the initial value is computed only once, on the first render, instead of being recalculated on every render.',null,null,'const [items, setItems] = useState(() => expensiveParse(rawData));','jsx','Useful when computing the initial value is expensive; passing `useState(expensiveParse(rawData))` directly would run that computation on every render even though only the first result is used.',ARRAY['react','state','performance']::text[],7),
('react','state','react-state-008','Local vs Global State',null,'Local state lives in a single component (or is lifted to a nearby parent); global state is accessible application-wide, typically via Context or a state management library.',null,null,null,'jsx','Prefer local state by default and only reach for global state when data genuinely needs to be shared across distant, unrelated parts of the tree.',ARRAY['react','state','architecture']::text[],8),
('redux','actions','redux-actions-001','Action object shape','{ type: ''domain/eventName'', payload?: any }','A Redux action is a plain JavaScript object that describes ''what happened''. It must have a `type` field, typically a string, and may carry additional data needed to update state.',null,null,'{ type: ''todos/added'', payload: { id: 1, text: ''Buy milk'' } }','javascript','Actions are the only way to send data into the store — they must be dispatched, never applied directly.',ARRAY['redux','actions','concepts']::text[],1),
('redux','actions','redux-actions-002','Action creator','const actionCreator = (payload) => ({ type: ''todos/added'', payload })','A function that constructs and returns an action object, avoiding the need to hand-write the object literal at every dispatch call site.',null,'A plain action object ready to be passed to dispatch().','const addTodo = (text) => ({ type: ''todos/added'', payload: text });
store.dispatch(addTodo(''Buy milk''));','javascript','With Redux Toolkit''s createSlice, action creators are generated automatically for each reducer you define.',ARRAY['redux','actions']::text[],2),
('redux','actions','redux-actions-003','Action types','const TODO_ADDED = ''todos/added'';','String constants used as the `type` field of actions, conventionally namespaced as ''feature/event'' (e.g. ''todos/added'') to avoid collisions between reducers.',null,null,'export const TODO_ADDED = ''todos/added'';
// used as: { type: TODO_ADDED, payload: ''Buy milk'' }','javascript','Defining types as constants avoids typos between where an action is dispatched and where it''s handled in a reducer.',ARRAY['redux','actions']::text[],3),
('redux','actions','redux-actions-004','Flux Standard Action (FSA)','{ type: string, payload?: any, error?: boolean, meta?: any }','A convention for shaping action objects consistently: a required `type`, an optional `payload` for the data, an optional `error` boolean, and an optional `meta` for extra context that isn''t part of the payload.',null,null,'{ type: ''todos/addFailed'', payload: new Error(''Network error''), error: true }','javascript','Redux Toolkit''s createAction/createSlice generate FSA-compliant actions by default.',ARRAY['redux','actions','conventions']::text[],4),
('redux','actions','redux-actions-005','Dispatching actions','dispatch(actionCreator(args))','The process of sending an action to the store via store.dispatch (or the useDispatch hook in React) so the reducer can compute new state.',null,null,'import { useDispatch } from ''react-redux'';
const dispatch = useDispatch();
dispatch(addTodo(''Buy milk''));','javascript','With thunk middleware installed, dispatch can also accept a function (a thunk) instead of a plain action object, enabling async logic.',ARRAY['redux','actions','dispatch']::text[],5),
('redux','actions','redux-actions-006','createAction()','createAction(type, prepareCallback?)','A Redux Toolkit utility that generates an FSA-compliant action creator for a given action type string, optionally using a ''prepare'' callback to customize the payload.','type — the action type string. prepareCallback — optional function that returns the { payload, meta } shape.','An action creator function with a `.type` property and a `.match()` type-guard method.','import { createAction } from ''@reduxjs/toolkit'';
const todoAdded = createAction(''todos/added'');
todoAdded(''Buy milk''); // { type: ''todos/added'', payload: ''Buy milk'' }','javascript','createSlice generates these for you automatically, so createAction is mostly used standalone outside of slices.',ARRAY['redux','actions','redux-toolkit']::text[],6),
('redux','async-integration','redux-async-integration-001','Middleware concept','const middleware = (storeAPI) => (next) => (action) => { ...; return next(action); }','Redux middleware sits between dispatching an action and it reaching the reducer, letting you intercept actions to log them, delay them, modify them, or handle async logic like API calls.','storeAPI — { getState, dispatch }. next — calls the next middleware in the chain (or the reducer). action — the dispatched action.','Typically the result of calling next(action), though middleware can also swallow or replace an action.','const logger = (store) => (next) => (action) => {
  console.log(''dispatching'', action);
  return next(action);
};','javascript','redux-thunk, redux-saga, and RTK Query are all implemented as middleware.',ARRAY['redux','async-integration','middleware']::text[],1),
('redux','async-integration','redux-async-integration-002','redux-thunk middleware','const thunk = (dispatch, getState) => { /* async logic, then dispatch(...) */ };','A middleware that allows dispatch() to accept a function (''thunk'') instead of a plain action object. The thunk receives dispatch and getState, letting it perform async work (like fetching data) and dispatch plain actions when it resolves.',null,null,'const fetchTodos = () => async (dispatch, getState) => {
  dispatch({ type: ''todos/loading'' });
  const res = await fetch(''/api/todos'');
  dispatch({ type: ''todos/loaded'', payload: await res.json() });
};
dispatch(fetchTodos());','javascript','redux-thunk is included by default in configureStore''s middleware, so no manual setup is needed in a standard Redux Toolkit app.',ARRAY['redux','async-integration','redux-thunk']::text[],2),
('redux','async-integration','redux-async-integration-003','createAsyncThunk() lifecycle','createAsyncThunk(''todos/fetch'', async (arg, thunkAPI) => { ... })','A Redux Toolkit function that wraps an async function and automatically dispatches three action types based on its outcome: ''pending'' when it starts, ''fulfilled'' when it resolves, and ''rejected'' when it throws or the promise rejects.','typePrefix — base string used to build the pending/fulfilled/rejected action types. payloadCreator — async function receiving (arg, thunkAPI) and returning the fulfilled payload.','A thunk action creator; dispatching it returns a promise that resolves to the fulfilled or rejected action.','export const fetchTodos = createAsyncThunk(''todos/fetch'', async () => {
  const res = await fetch(''/api/todos'');
  return res.json();
});
// generates: todos/fetch/pending, todos/fetch/fulfilled, todos/fetch/rejected','javascript','Handle the three generated action types in a slice''s extraReducers to drive loading/success/error UI state.',ARRAY['redux','async-integration','redux-toolkit']::text[],3),
('redux','async-integration','redux-async-integration-004','Handling createAsyncThunk in extraReducers','builder.addCase(thunk.pending, ...).addCase(thunk.fulfilled, ...).addCase(thunk.rejected, ...)','The standard pattern for reacting to a createAsyncThunk''s lifecycle inside a slice — setting a loading flag on pending, storing the result on fulfilled, and storing the error on rejected.',null,null,'extraReducers: (builder) => {
  builder
    .addCase(fetchTodos.pending, (state) => { state.status = ''loading''; })
    .addCase(fetchTodos.fulfilled, (state, action) => {
      state.status = ''idle'';
      state.items = action.payload;
    })
    .addCase(fetchTodos.rejected, (state, action) => {
      state.status = ''error'';
      state.error = action.error.message;
    });
}','javascript','action.error (not action.payload) holds the error info on the rejected case, unless you use rejectWithValue in the thunk.',ARRAY['redux','async-integration','redux-toolkit']::text[],4),
('redux','async-integration','redux-async-integration-005','redux-saga overview',null,'A middleware that manages side effects using ES6 generator functions, letting you write async workflows (including cancellation, debouncing, and complex sequencing) as sagas that listen for dispatched actions and yield declarative effects.',null,null,'function* fetchTodosSaga() {
  const todos = yield call(api.getTodos);
  yield put({ type: ''todos/loaded'', payload: todos });
}
function* rootSaga() {
  yield takeEvery(''todos/fetch'', fetchTodosSaga);
}','javascript','More powerful but more complex than redux-thunk; commonly chosen for apps with intricate async flows like websockets, polling, or race conditions between requests.',ARRAY['redux','async-integration','redux-saga']::text[],5),
('redux','async-integration','redux-async-integration-006','RTK Query queries','builder.query({ query: (arg) => `todos/${arg}` })','An RTK Query endpoint definition for fetching (read) data, which auto-generates a React hook (e.g. useGetTodoQuery) that returns data, isLoading, isError/error, and handles caching and automatic re-fetching.',null,'A hook returning { data, isLoading, isFetching, isError, error, refetch }.','endpoints: (builder) => ({
  getTodo: builder.query({ query: (id) => `todos/${id}` })
})
// usage: const { data, isLoading } = useGetTodoQuery(id);','javascript','Query results are cached by endpoint name + argument, so multiple components calling the same query hook share one request.',ARRAY['redux','async-integration','rtk-query']::text[],6),
('redux','async-integration','redux-async-integration-007','RTK Query mutations','builder.mutation({ query: (body) => ({ url: ''todos'', method: ''POST'', body }) })','An RTK Query endpoint definition for creating/updating/deleting data, generating a hook (e.g. useAddTodoMutation) that returns a trigger function plus the request''s status, and that can invalidate cached queries via tags.',null,'A hook returning [triggerFn, { data, isLoading, isError, error }].','endpoints: (builder) => ({
  addTodo: builder.mutation({
    query: (body) => ({ url: ''todos'', method: ''POST'', body }),
    invalidatesTags: [''Todo'']
  })
})
// usage: const [addTodo, { isLoading }] = useAddTodoMutation();','javascript','providesTags/invalidatesTags drive automatic cache invalidation — a mutation invalidating a tag triggers re-fetching of queries that provide it.',ARRAY['redux','async-integration','rtk-query']::text[],7),
('redux','async-integration','redux-async-integration-008','rejectWithValue()','createAsyncThunk(''todos/add'', async (todo, { rejectWithValue }) => { ... })','A helper available on a createAsyncThunk''s thunkAPI used to return a custom, serializable error payload on failure, so it ends up in action.payload of the rejected action instead of the generic action.error.',null,null,'createAsyncThunk(''todos/add'', async (todo, { rejectWithValue }) => {
  try {
    return await api.addTodo(todo);
  } catch (err) {
    return rejectWithValue(err.response.data);
  }
});','javascript','Check action.payload (not action.error) in the rejected case reducer when rejectWithValue is used.',ARRAY['redux','async-integration','redux-toolkit']::text[],8),
('redux','reducers','redux-reducers-001','Reducer function','(state, action) => newState','A pure function that takes the current state and an action, and returns the next state. Reducers describe how state changes in response to actions, without performing the changes directly.','state — the current state (or undefined on the first call). action — the dispatched action object.','The next state value.','function counterReducer(state = 0, action) {
  switch (action.type) {
    case ''counter/incremented'': return state + 1;
    default: return state;
  }
}','javascript',null,ARRAY['redux','reducers','concepts']::text[],1),
('redux','reducers','redux-reducers-002','Pure function requirement',null,'Reducers must be pure: given the same state and action, they always return the same output, and they must not mutate arguments, make API calls, generate random values, or cause other side effects.',null,null,null,null,'Purity is what makes Redux state predictable and enables features like time-travel debugging and hot reloading.',ARRAY['redux','reducers','concepts']::text[],2),
('redux','reducers','redux-reducers-003','combineReducers()','combineReducers({ key1: reducer1, key2: reducer2 })','Combines multiple slice reducers into a single root reducer, where each key in the resulting state object is managed by its corresponding reducer function.','An object mapping state keys to the reducer function responsible for that slice of state.','A single reducer function that calls each child reducer and assembles the combined state object.','import { combineReducers } from ''redux'';
const rootReducer = combineReducers({ todos: todosReducer, user: userReducer });','javascript','When using configureStore, passing an object as the `reducer` option calls combineReducers for you automatically.',ARRAY['redux','reducers']::text[],3),
('redux','reducers','redux-reducers-004','Immutability in reducers',null,'Reducers must never mutate the existing state object — they must return a new state object (or the same reference if nothing changed) built with techniques like spreading or array copy methods.',null,null,'// Wrong: state.count++
// Right:
return { ...state, count: state.count + 1 };','javascript','Redux Toolkit''s createSlice uses Immer internally, letting you write reducers with ''mutating'' syntax that is converted to safe immutable updates.',ARRAY['redux','reducers','immutability']::text[],4),
('redux','reducers','redux-reducers-005','Switch-based reducer pattern','switch (action.type) { case ''...'': ...; default: return state; }','The classic style of writing a Redux reducer as a switch statement over action.type, with each case returning the appropriately updated state.',null,null,'function todosReducer(state = [], action) {
  switch (action.type) {
    case ''todos/added'':
      return [...state, action.payload];
    default:
      return state;
  }
}','javascript','Still common in legacy code and interviews; createSlice replaces this with a plain object of case reducer functions.',ARRAY['redux','reducers','legacy']::text[],5),
('redux','reducers','redux-reducers-006','Initial state','function reducer(state = initialState, action) { ... }','The default value a reducer returns when the store is first created and no state exists yet, provided via a default parameter for the `state` argument.',null,null,'const initialState = { count: 0 };
function counterReducer(state = initialState, action) { /* ... */ }','javascript','Redux calls every reducer once with an internal @@INIT action to populate this initial state.',ARRAY['redux','reducers']::text[],6),
('redux','reducers','redux-reducers-007','Default case','default: return state;','The fallback branch in a switch-based reducer that returns the unchanged current state for any action type the reducer doesn''t recognize.',null,null,null,null,'Omitting the default case (or otherwise failing to return the existing state) causes the reducer to return undefined for unrelated actions, which is a common Redux bug.',ARRAY['redux','reducers']::text[],7),
('redux','redux-toolkit','redux-redux-toolkit-001','Why Redux Toolkit exists',null,'Redux Toolkit (RTK) is the official, recommended way to write Redux logic. It was created to address common complaints about classic Redux — too much boilerplate, too many packages to configure, and easy-to-make mutation mistakes — by bundling sensible defaults and utilities like createSlice, configureStore, and Immer.',null,null,null,null,'The Redux docs now consider hand-written createStore/combineReducers/switch-reducer code a legacy pattern; RTK is the standard for new projects.',ARRAY['redux','redux-toolkit','concepts']::text[],1),
('redux','redux-toolkit','redux-redux-toolkit-002','createReducer()','createReducer(initialState, (builder) => { builder.addCase(...) })','A Redux Toolkit utility for writing a reducer as a map of action types to case reducer functions (using a builder callback) instead of a switch statement, with Immer-powered ''mutating'' update syntax.','initialState — the reducer''s default state. builder — object with addCase(), addMatcher(), and addDefaultCase() methods to register handlers.','A reducer function suitable for combineReducers or configureStore.','const counterReducer = createReducer(0, (builder) => {
  builder.addCase(''counter/incremented'', (state) => state + 1);
});','javascript','createSlice uses createReducer internally — most apps use createSlice directly rather than calling createReducer standalone.',ARRAY['redux','redux-toolkit']::text[],2),
('redux','redux-toolkit','redux-redux-toolkit-003','Immer immutability in RTK',null,'Redux Toolkit uses the Immer library internally so that code written inside createSlice/createReducer can ''mutate'' a draft state object using normal JavaScript syntax, while Immer produces a correctly immutable next state behind the scenes.',null,null,'// Inside a slice reducer, this is safe and produces an immutable update:
state.todos.push(newTodo);','javascript','Immer only applies inside RTK''s reducer builders — plain hand-written reducers outside createSlice/createReducer still must not mutate state.',ARRAY['redux','redux-toolkit','immer']::text[],3),
('redux','redux-toolkit','redux-redux-toolkit-004','RTK Query overview',null,'RTK Query is a data-fetching and caching layer built into Redux Toolkit. It generates hooks like useGetTodosQuery from an API definition, automatically handling loading/error state, caching, re-fetching, and cache invalidation without hand-written thunks or reducers.',null,null,'import { createApi, fetchBaseQuery } from ''@reduxjs/toolkit/query/react'';
const api = createApi({
  baseQuery: fetchBaseQuery({ baseUrl: ''/api'' }),
  endpoints: (builder) => ({
    getTodos: builder.query({ query: () => ''todos'' })
  })
});
export const { useGetTodosQuery } = api;','javascript','RTK Query is often described as eliminating the need to hand-write data-fetching thunks, reducers, and selectors for server state.',ARRAY['redux','redux-toolkit','rtk-query']::text[],4),
('redux','redux-toolkit','redux-redux-toolkit-005','createEntityAdapter()','createEntityAdapter({ selectId, sortComparer })','A Redux Toolkit utility that generates a set of prebuilt reducers and selectors for managing a normalized collection of items (keyed by id) in a slice, such as adding, updating, and removing entities.','selectId — optional function to extract an item''s id. sortComparer — optional function to keep the collection sorted.','An adapter object with getInitialState(), reducer methods (addOne, updateOne, removeOne, etc.), and getSelectors().','const todosAdapter = createEntityAdapter();
const todosSlice = createSlice({
  name: ''todos'',
  initialState: todosAdapter.getInitialState(),
  reducers: {
    added: todosAdapter.addOne
  }
});','javascript','Normalizing collections by id avoids deeply nested/duplicated data and makes lookups O(1).',ARRAY['redux','redux-toolkit','normalization']::text[],5),
('redux','redux-toolkit','redux-redux-toolkit-006','Matcher utilities (isPending, isFulfilled, isRejected)','builder.addMatcher(isPending, (state) => { state.loading = true; })','Redux Toolkit ships matcher functions that identify action types generated by any createAsyncThunk (or a specific one), for use with extraReducers'' addMatcher to handle loading/success/error state generically across multiple thunks.','isPending / isFulfilled / isRejected — matcher functions, usable standalone or scoped to specific thunks via isPending(thunkA, thunkB).',null,'import { isPending } from ''@reduxjs/toolkit'';
builder.addMatcher(isPending, (state) => { state.loading = true; });','javascript','Useful for a shared ''any request is loading'' flag without listing every thunk''s pending case individually.',ARRAY['redux','redux-toolkit','async']::text[],6),
('redux','redux-toolkit','redux-redux-toolkit-007','createListenerMiddleware()','const listenerMiddleware = createListenerMiddleware();','A Redux Toolkit middleware for running side-effect logic in response to dispatched actions or state changes, as a lighter-weight alternative to redux-saga for reactive async workflows.',null,'A middleware instance with a `.startListening()` method to register listeners and a `.middleware` to add to the store.','const listenerMiddleware = createListenerMiddleware();
listenerMiddleware.startListening({
  actionCreator: todoAdded,
  effect: async (action, api) => { /* side effect */ }
});','javascript','Added in newer versions of Redux Toolkit as a built-in alternative to reaching for redux-saga or redux-observable for simpler cases.',ARRAY['redux','redux-toolkit','middleware']::text[],7),
('redux','redux-toolkit','redux-redux-toolkit-008','Redux DevTools integration',null,'configureStore automatically wires up the Redux DevTools browser extension in development, enabling action logging, state diffing, and time-travel debugging with zero manual setup.',null,null,null,null,'In classic Redux this required manually composing `window.__REDUX_DEVTOOLS_EXTENSION_COMPOSE__` with your store enhancers.',ARRAY['redux','redux-toolkit','devtools']::text[],8),
('redux','redux-toolkit','redux-redux-toolkit-009','Default middleware in RTK',null,'configureStore automatically includes redux-thunk for async logic plus development-only middleware that warns on state mutations and non-serializable values placed in actions or state.',null,null,'configureStore({
  reducer: rootReducer,
  middleware: (getDefaultMiddleware) => getDefaultMiddleware().concat(logger)
});','javascript','Use getDefaultMiddleware() and .concat()/.prepend() to add custom middleware without losing the built-in checks.',ARRAY['redux','redux-toolkit','middleware']::text[],9),
('redux','redux-toolkit','redux-redux-toolkit-010','PayloadAction<T> (TypeScript)','reducers: { added: (state, action: PayloadAction<string>) => {...} }','A generic type Redux Toolkit provides for typing the action objects passed into slice reducers, so `action.payload` has a concrete type instead of `any` in TypeScript projects.',null,null,'import { PayloadAction } from ''@reduxjs/toolkit'';
reducers: {
  added: (state, action: PayloadAction<string>) => { state.push(action.payload); }
}','typescript','Without PayloadAction, TypeScript infers action.payload as unknown/any inside createSlice reducers.',ARRAY['redux','redux-toolkit','typescript']::text[],10),
('redux','selectors','redux-selectors-001','Selector function','const selectTodos = (state) => state.todos;','A function that takes the Redux store state and returns some derived piece of it. Selectors centralize the knowledge of how state is shaped, so components don''t need to know the state tree''s structure.',null,'The selected (or derived) piece of state.','const selectTodoCount = (state) => state.todos.length;','javascript','Co-locating selectors next to their slice (e.g. exported from the slice file) makes it easy to update them if the state shape changes.',ARRAY['redux','selectors','concepts']::text[],1),
('redux','selectors','redux-selectors-002','useSelector()','const value = useSelector(selectorFn)','A react-redux hook that reads a value from the Redux store state by running the given selector function, and re-renders the component whenever the selected value changes.','selectorFn — function receiving the store state and returning the desired value.','The value returned by the selector.','import { useSelector } from ''react-redux'';
const todos = useSelector((state) => state.todos.items);','javascript','useSelector compares the selected value with strict equality (===) by default — return primitives or memoized references to avoid unnecessary re-renders.',ARRAY['redux','selectors','react-redux']::text[],2),
('redux','selectors','redux-selectors-003','createSelector() (reselect)','createSelector(inputSelectors, resultFn)','A function from the Reselect library (re-exported by Redux Toolkit) that creates a memoized selector, recomputing its result only when one of its input selectors'' outputs changes.','inputSelectors — one or more selector functions whose results are passed to resultFn. resultFn — combines the inputs into a derived value.','A memoized selector function.','import { createSelector } from ''@reduxjs/toolkit'';
const selectCompletedCount = createSelector(
  (state) => state.todos.items,
  (items) => items.filter(t => t.completed).length
);','javascript','Essential for expensive derived computations (filtering, sorting, aggregating) so they don''t rerun on every render.',ARRAY['redux','selectors','memoization']::text[],3),
('redux','selectors','redux-selectors-004','Deriving state with selectors',null,'Rather than storing computed values in the store, selectors compute derived data (filtered lists, totals, formatted values) on read, keeping the stored state minimal and normalized.',null,null,'const selectActiveTodos = (state) => state.todos.items.filter(t => !t.done);','javascript','Storing only raw data and deriving the rest avoids state getting out of sync.',ARRAY['redux','selectors','concepts']::text[],4),
('redux','selectors','redux-selectors-005','Avoiding unnecessary re-renders with selectors',null,'Selecting the smallest, most specific piece of state needed (rather than a whole object) and memoizing derived values with createSelector prevents components from re-rendering when unrelated state changes.',null,null,'// Prefer:
useSelector((state) => state.todos.count);
// Over selecting the whole todos object and reading .count in the component','javascript','Returning a new object/array literal from a plain useSelector call causes a re-render on every dispatch, since a new reference never equals the previous one.',ARRAY['redux','selectors','performance']::text[],5),
('redux','selectors','redux-selectors-006','useSelector with shallowEqual','useSelector(selectorFn, shallowEqual)','Passes an equality function as the second argument to useSelector so it re-renders only when the selected object''s top-level fields actually change, instead of on every new object reference.',null,null,'import { useSelector, shallowEqual } from ''react-redux'';
const { count, name } = useSelector((state) => ({
  count: state.todos.count,
  name: state.user.name
}), shallowEqual);','javascript','An alternative to this is calling useSelector multiple times, once per primitive value needed.',ARRAY['redux','selectors','react-redux']::text[],6),
('redux','slices','redux-slices-001','createSlice()','createSlice({ name, initialState, reducers, extraReducers })','The core Redux Toolkit function that generates a slice of the store — a reducer function plus its matching action creators — from a name, an initial state, and an object of reducer functions.','name — string prefix used to namespace generated action types. initialState — the slice''s default state. reducers — object of case reducer functions. extraReducers — optional handlers for actions defined outside this slice.','A slice object with `.reducer`, `.actions`, `.caseReducers`, and `.name` properties.','import { createSlice } from ''@reduxjs/toolkit'';
const todosSlice = createSlice({
  name: ''todos'',
  initialState: [],
  reducers: {
    added: (state, action) => { state.push(action.payload); }
  }
});','javascript','createSlice is the standard, recommended way to write Redux logic today — it removes most of the boilerplate of hand-written action types, action creators, and switch statements.',ARRAY['redux','slices','redux-toolkit']::text[],1),
('redux','slices','redux-slices-002','Slice reducers use Immer',null,'Reducer functions written inside createSlice''s `reducers` field are run through Immer under the hood, so you can write code that looks like it mutates `state` directly (e.g. state.push(item)) while Immer safely produces an immutable update.',null,null,'reducers: {
  incremented: (state) => { state.value += 1; } // looks mutating, is safe
}','javascript','You can still return a new state value explicitly instead of mutating draft state, but not both in the same case reducer.',ARRAY['redux','slices','immer']::text[],2),
('redux','slices','redux-slices-003','extraReducers','extraReducers: (builder) => { builder.addCase(actionCreator, (state, action) => {...}) }','A field on createSlice used to let a slice respond to actions that were defined elsewhere, such as action types from createAsyncThunk or actions from other slices.','builder — a builder object with addCase(), addMatcher(), and addDefaultCase() methods.',null,'extraReducers: (builder) => {
  builder.addCase(fetchTodos.fulfilled, (state, action) => {
    state.items = action.payload;
  });
}','javascript','Use extraReducers instead of `reducers` for any action type the slice itself doesn''t define — this keeps action type strings unique.',ARRAY['redux','slices','redux-toolkit']::text[],3),
('redux','slices','redux-slices-004','slice.actions','const { added, removed } = todosSlice.actions;','The object of auto-generated action creators returned by createSlice, one for each key defined in the `reducers` field, typically destructured and exported.',null,'An object mapping each reducer name to its corresponding action creator function.','export const { added, removed } = todosSlice.actions;
dispatch(added(''Buy milk''));','javascript',null,ARRAY['redux','slices','redux-toolkit']::text[],4),
('redux','slices','redux-slices-005','slice.reducer','export default todosSlice.reducer;','The combined reducer function generated by createSlice, handling both the slice''s own actions and any extraReducers, ready to be passed into configureStore.',null,null,'export default todosSlice.reducer;
// in the store:
configureStore({ reducer: { todos: todosReducer } });','javascript',null,ARRAY['redux','slices','redux-toolkit']::text[],5),
('redux','slices','redux-slices-006','Slice naming convention',null,'The `name` passed to createSlice namespaces every generated action type as ''`name`/`reducerKey`'' (e.g. ''todos/added''), which keeps action types unique across slices and readable in the Redux DevTools.',null,null,'createSlice({ name: ''todos'', ... }); // generates types like ''todos/added''','javascript','Two slices with the same `name` will silently generate colliding action types — keep slice names unique per store.',ARRAY['redux','slices','conventions']::text[],6),
('redux','store','redux-store-001','configureStore()','configureStore({ reducer, middleware, devTools, preloadedState, enhancers })','The Redux Toolkit function for creating a Redux store. It wraps createStore with good defaults — Redux DevTools support, redux-thunk middleware, and dev-mode checks for mutations and non-serializable values.','reducer — root reducer function or an object of slice reducers (combined automatically). middleware — optional callback to customize the default middleware array. preloadedState — optional initial state.','A configured Redux store instance with dispatch, getState, subscribe, and replaceReducer.','import { configureStore } from ''@reduxjs/toolkit'';
const store = configureStore({ reducer: { todos: todosReducer } });','javascript','Use configureStore instead of the legacy createStore in all new Redux code — it is the standard approach recommended by the Redux team.',ARRAY['redux','store','redux-toolkit']::text[],1),
('redux','store','redux-store-002','createStore() (legacy)','createStore(reducer, preloadedState, enhancer)','The original, low-level Redux API for creating a store from a root reducer. Superseded by configureStore, which sets up sensible defaults automatically.','reducer — root reducer function. preloadedState — optional initial state. enhancer — optional store enhancer such as applyMiddleware.','A Redux store instance.','import { createStore } from ''redux'';
const store = createStore(rootReducer);','javascript','Deprecated in favor of configureStore; still shows up in legacy codebases and interview questions about ''classic'' Redux.',ARRAY['redux','store','legacy']::text[],2),
('redux','store','redux-store-003','store.getState()','store.getState()','Returns the current state tree of the Redux store.',null,'The current state value, exactly as computed by the root reducer.','const state = store.getState();
console.log(state.todos.length);','javascript','Treat the returned state as read-only — never mutate it directly; dispatch an action instead.',ARRAY['redux','store']::text[],3),
('redux','store','redux-store-004','store.dispatch()','store.dispatch(action)','Sends an action to the store, triggering the root reducer to compute the next state.','action — a plain object with a `type` field (or a thunk/function when thunk middleware is installed).','The dispatched action, for convenience (unless middleware changes this, as with thunks).','store.dispatch({ type: ''todos/added'', payload: ''Buy milk'' });','javascript','dispatch() is the only way to trigger a state change in Redux — components never modify state directly.',ARRAY['redux','store']::text[],4),
('redux','store','redux-store-005','store.subscribe()','store.subscribe(listener)','Registers a callback that runs every time an action is dispatched and the state tree may have changed.','listener — function called with no arguments after each dispatch.','An unsubscribe function that removes the listener when called.','const unsubscribe = store.subscribe(() => console.log(store.getState()));
unsubscribe(); // stop listening','javascript','In React apps, react-redux''s useSelector/Provider handle subscriptions for you — manual subscribe() is rarely needed.',ARRAY['redux','store']::text[],5),
('redux','store','redux-store-006','Single store principle',null,'A Redux application uses exactly one store holding the entire application state tree, rather than multiple stores per feature. Different pieces of state are organized by combining reducers, not by creating separate stores.',null,null,null,null,'This is one of Redux''s three core principles, alongside ''state is read-only'' and ''changes are made with pure functions''. It keeps debugging, persistence, and DevTools time-travel simple.',ARRAY['redux','store','concepts']::text[],6),
('redux','store','redux-store-007','Store enhancers','createStore(reducer, enhancer) / configureStore({ enhancers })','A store enhancer is a higher-order function that composes over the store creator to add capabilities, such as middleware support (applyMiddleware) or persistence.',null,null,'import { applyMiddleware, createStore } from ''redux'';
const store = createStore(rootReducer, applyMiddleware(logger));','javascript','configureStore applies the middleware enhancer for you automatically, so manual applyMiddleware is mostly a legacy pattern now.',ARRAY['redux','store','middleware']::text[],7),
('zustand','actions','zustand-actions-001','Defining actions in the store',null,'Actions are just functions defined alongside state inside the create() callback, closing over set (and optionally get) to update the store.',null,null,'const useCounterStore = create((set) => ({
  count: 0,
  increment: () => set((s) => ({ count: s.count + 1 })),
  reset: () => set({ count: 0 }),
}));','javascript','Because actions live on the same object as state, they are automatically available wherever the store hook is used — no dispatch or action types required.',ARRAY['zustand','actions','store']::text[],1),
('zustand','actions','zustand-actions-002','Calling actions from components','const doThing = useStore((state) => state.doThing)','Components select an action from the store using the hook, the same way they select state, and call it directly like a normal function.',null,null,'function Counter() {
  const count = useCounterStore((s) => s.count);
  const increment = useCounterStore((s) => s.increment);
  return <button onClick={increment}>{count}</button>;
}','jsx','Action references are stable across renders, so selecting them doesn''t cause unnecessary re-renders.',ARRAY['zustand','actions','hooks']::text[],2),
('zustand','actions','zustand-actions-003','Actions updating state via set()',null,'Actions update the store exclusively by calling set() with a partial state or an updater function — there is no separate reducer/dispatch step like in Redux.',null,null,'addTodo: (text) => set((state) => ({
  todos: [...state.todos, { text, done: false }],
})),','javascript','Because set() merges shallowly, an action only needs to return the keys it changes.',ARRAY['zustand','actions','set']::text[],3),
('zustand','actions','zustand-actions-004','Actions calling other actions','get().otherAction()','Actions can call other actions on the same store via get(), enabling composition without duplicating logic.',null,null,'const useStore = create((set, get) => ({
  count: 0,
  increment: () => set((s) => ({ count: s.count + 1 })),
  incrementTwice: () => { get().increment(); get().increment(); },
}));','javascript','Keep composed action chains simple — deeply nested calls can make state changes harder to trace.',ARRAY['zustand','actions','composition']::text[],4),
('zustand','actions','zustand-actions-005','Actions outside components','useStore.getState().action()','Because actions are plain functions on the store, they can be invoked outside React (e.g. in event handlers, utilities, or tests) via getState().',null,null,'// In a non-component utility file
useCounterStore.getState().increment();','javascript','This avoids needing to pass actions down as props or through context for non-component code.',ARRAY['zustand','actions','vanilla']::text[],5),
('zustand','actions','zustand-actions-006','Grouping actions in an actions object',null,'For larger stores, actions are sometimes grouped under a nested actions key (e.g. state.actions.increment) to visually separate them from data fields.',null,null,'const useStore = create((set) => ({
  count: 0,
  actions: {
    increment: () => set((s) => ({ count: s.count + 1 })),
  },
}));','javascript','This is a convention, not a Zustand requirement — it helps when a store has many actions and you want to select ''actions'' as a stable group.',ARRAY['zustand','actions','conventions']::text[],6),
('zustand','async-integration','zustand-async-integration-001','Async actions',null,'Zustand has no special API for async logic — actions can simply be async functions that call set() before and after an awaited operation, such as a fetch call.',null,null,'const useUserStore = create((set) => ({
  user: null,
  loading: false,
  fetchUser: async (id) => {
    set({ loading: true });
    const res = await fetch(`/api/users/${id}`);
    set({ user: await res.json(), loading: false });
  },
}));','javascript','Since set() is synchronous and side-effect free, you can call it any number of times before, during, and after an await.',ARRAY['zustand','async-integration','async']::text[],1),
('zustand','async-integration','zustand-async-integration-002','Handling async errors',null,'Async actions typically wrap the awaited call in try/catch and store an error field in state, so components can render loading/error/success states.',null,null,'fetchUser: async (id) => {
  set({ loading: true, error: null });
  try {
    const res = await fetch(`/api/users/${id}`);
    set({ user: await res.json(), loading: false });
  } catch (err) {
    set({ error: err.message, loading: false });
  }
},','javascript',null,ARRAY['zustand','async-integration','error-handling']::text[],2),
('zustand','async-integration','zustand-async-integration-003','persist middleware','import { persist } from ''zustand/middleware''
create(persist(stateCreator, { name: ''storage-key'' }))','The persist middleware automatically saves store state to storage (localStorage by default) and rehydrates it on load, keeping state across page refreshes.','stateCreator — the store creator function. options.name — the storage key. options.storage — optional custom storage adapter.','A wrapped state creator to pass into create().','const useStore = create(
  persist(
    (set) => ({ theme: ''light'', setTheme: (theme) => set({ theme }) }),
    { name: ''app-settings'' }
  )
);','javascript','Use the `partialize` option to persist only specific fields instead of the entire store.',ARRAY['zustand','async-integration','middleware']::text[],3),
('zustand','async-integration','zustand-async-integration-004','devtools middleware','import { devtools } from ''zustand/middleware''
create(devtools(stateCreator))','The devtools middleware connects a store to the Redux DevTools browser extension, letting you inspect state and action history during development.','stateCreator — the store creator function. options.name — optional label shown in DevTools.','A wrapped state creator to pass into create().','const useStore = create(
  devtools((set) => ({ count: 0, increment: () => set((s) => ({ count: s.count + 1 })) }))
);','javascript','Named set() calls (set(fn, false, ''increment'')) show up as labeled actions in the DevTools timeline.',ARRAY['zustand','async-integration','devtools']::text[],4),
('zustand','async-integration','zustand-async-integration-005','immer middleware','import { immer } from ''zustand/middleware/immer''
create(immer(stateCreator))','The immer middleware lets actions write ''mutating'' update logic against a draft state, while immer produces an immutable update under the hood.','stateCreator — the store creator function, where set() accepts a draft-mutating recipe function.','A wrapped state creator to pass into create().','const useStore = create(
  immer((set) => ({
    todos: [],
    addTodo: (text) => set((draft) => { draft.todos.push({ text, done: false }); }),
  }))
);','javascript','Useful for deeply nested state where manual spreading becomes verbose; requires the `immer` package as a dependency.',ARRAY['zustand','async-integration','immer']::text[],5),
('zustand','async-integration','zustand-async-integration-006','Combining middleware','create(devtools(persist(immer(stateCreator), options)))','Zustand middleware functions can be composed by nesting them around the state creator, applying each one''s behavior to the resulting store.',null,'A wrapped state creator with all composed middleware applied.','const useStore = create(
  devtools(
    persist(
      (set) => ({ count: 0 }),
      { name: ''counter'' }
    )
  )
);','javascript','Order matters — middleware closer to the state creator runs first; check each middleware''s docs for recommended ordering.',ARRAY['zustand','async-integration','middleware']::text[],6),
('zustand','async-integration','zustand-async-integration-007','Slice pattern',null,'For larger stores, state and actions are split into separate ''slice'' creator functions that are combined into one store via create(), keeping each domain''s logic in its own module.',null,null,'const createBearSlice = (set) => ({
  bears: 0,
  addBear: () => set((s) => ({ bears: s.bears + 1 })),
});
const createFishSlice = (set) => ({
  fish: 0,
  addFish: () => set((s) => ({ fish: s.fish + 1 })),
});
const useStore = create((...a) => ({
  ...createBearSlice(...a),
  ...createFishSlice(...a),
}));','javascript','All slices share the same set/get, so a single store is still produced — this is an organizational pattern, not multiple stores.',ARRAY['zustand','async-integration','slices']::text[],7),
('zustand','async-integration','zustand-async-integration-008','subscribeWithSelector middleware','import { subscribeWithSelector } from ''zustand/middleware''
create(subscribeWithSelector(stateCreator))','Adds an enhanced subscribe() method to the store that accepts a selector and listener, allowing code outside React to react to changes in a specific slice of state.','stateCreator — the store creator function.','A wrapped state creator whose store exposes subscribe(selector, listener, options?).','const useStore = create(subscribeWithSelector((set) => ({ count: 0 })));
useStore.subscribe((state) => state.count, (count) => console.log(''count changed'', count));','javascript','Without this middleware, store.subscribe() only fires on any state change and passes the full state, not a selected slice.',ARRAY['zustand','async-integration','middleware']::text[],8),
('zustand','selectors','zustand-selectors-001','Selecting a slice of state','const slice = useStore((state) => state.slice)','Passing a selector function to the store hook subscribes a component to only that piece of state, so it re-renders only when that specific value changes.','selector — function (state) => selectedValue.','The value returned by the selector.','const bears = useBearStore((state) => state.bears);
// Component only re-renders when `bears` changes, not on unrelated state updates','jsx','Avoid selecting the whole state object (useStore()) unless the component genuinely needs everything — it re-renders on every store change.',ARRAY['zustand','selectors','performance']::text[],1),
('zustand','selectors','zustand-selectors-002','Selector functions as a core concept',null,'In Zustand, the selector passed to the hook is the primary API for controlling re-renders — instead of memoizing components, you narrow what each component subscribes to.',null,null,'// Selects and derives in one step
const bearCount = useBearStore((state) => state.bears.length);','javascript','Selectors can also compute derived values inline, avoiding extra state fields just for derived data.',ARRAY['zustand','selectors','fundamentals']::text[],2),
('zustand','selectors','zustand-selectors-003','Selecting multiple values','const { a, b } = useStore((state) => ({ a: state.a, b: state.b }))','A selector can return an object or array combining multiple state values, but by default a new object is created on every call, causing re-renders even when the underlying values haven''t changed.',null,'An object or array of the selected values.','const { bears, fish } = useStore((state) => ({
  bears: state.bears,
  fish: state.fish,
}));','javascript','Without a custom equality check, this pattern re-renders on every store update — pair it with useShallow to fix that.',ARRAY['zustand','selectors','re-renders']::text[],3),
('zustand','selectors','zustand-selectors-004','useShallow()','import { useShallow } from ''zustand/react/shallow''
const { a, b } = useStore(useShallow((state) => ({ a: state.a, b: state.b })))','useShallow wraps a selector so the returned object/array is compared with shallow equality, preventing re-renders when the selected values themselves haven''t changed.','selector — function returning an object or array of selected values.','The selected object/array, memoized by shallow comparison across renders.','const { bears, fish } = useStore(
  useShallow((state) => ({ bears: state.bears, fish: state.fish }))
);','javascript','This is the recommended replacement for the older shallow equality function passed as a second hook argument in Zustand v4.',ARRAY['zustand','selectors','shallow']::text[],4),
('zustand','selectors','zustand-selectors-005','shallow equality function','import { shallow } from ''zustand/shallow''','shallow is a standalone comparator that checks top-level equality between two objects/arrays, used internally by useShallow and available for manual comparisons.',null,'true if all top-level keys/values are reference-equal, false otherwise.','import { shallow } from ''zustand/shallow'';
shallow({ a: 1 }, { a: 1 }); // true','javascript','In Zustand v4 this could be passed directly as a second argument to the store hook; v5 recommends useShallow instead.',ARRAY['zustand','selectors','shallow']::text[],5),
('zustand','selectors','zustand-selectors-006','Selecting whole state (anti-pattern)','const state = useStore()','Calling the store hook with no selector returns the entire state object and subscribes the component to every change in the store.',null,'The full state object.','// Re-renders on ANY store change, even unrelated fields
const state = useBearStore();','javascript','Reserve this for debugging or components that truly depend on most of the store — otherwise select only what you need.',ARRAY['zustand','selectors','performance']::text[],6),
('zustand','state','zustand-state-001','Reading state via the hook','const value = useStore((state) => state.value)','Components read store state by calling the store hook with a selector function, which subscribes the component to just that piece of state.','selector — a function that receives the full state object and returns the piece(s) needed.','The value returned by the selector function.','function Bears() {
  const bears = useBearStore((state) => state.bears);
  return <p>{bears}</p>;
}','jsx','Only components that read a piece of state re-render when that piece changes, since each selector creates its own subscription.',ARRAY['zustand','state','hooks']::text[],1),
('zustand','state','zustand-state-002','set()','set(partialStateOrFn, replace?)','The set() function passed into create() updates the store''s state; it accepts either a partial state object or a function that receives the current state and returns a partial update.','partialStateOrFn — an object merged into state, or a function (state) => partialState. replace — optional boolean; when true, replaces the whole state instead of merging.','undefined — set() triggers a re-render of subscribed components as a side effect.','const useStore = create((set) => ({
  count: 0,
  increment: () => set((state) => ({ count: state.count + 1 })),
}));','javascript','Prefer the functional form (state) => (...) when the update depends on the previous state, to avoid stale closures.',ARRAY['zustand','state','set']::text[],2),
('zustand','state','zustand-state-003','get()','get()','The get() function passed into create() returns the store''s current state, letting actions read up-to-date values without depending on React''s render cycle.',null,'The current state object at the time get() is called.','const useStore = create((set, get) => ({
  count: 0,
  logCount: () => console.log(get().count),
}));','javascript','get() is most useful inside actions that need to read other state values or compose logic before calling set().',ARRAY['zustand','state','get']::text[],3),
('zustand','state','zustand-state-004','Partial updates / shallow merging',null,'By default, set() shallow-merges the object you pass into the existing state, so you only need to specify the keys that changed.',null,null,'// State: { count: 0, name: ''Bear'' }
set({ count: 1 }); // -> { count: 1, name: ''Bear'' }','javascript','Merging is shallow only — nested objects/arrays must be spread manually or replaced entirely, they are not deep-merged.',ARRAY['zustand','state','immutability']::text[],4),
('zustand','state','zustand-state-005','Immutability best practice',null,'State updates in Zustand should be immutable: create new objects/arrays instead of mutating existing ones, since Zustand relies on reference changes to notify subscribers.',null,null,'// Good
set((state) => ({ items: [...state.items, newItem] }));
// Bad — mutates in place, won''t trigger a re-render reliably
// state.items.push(newItem);','javascript','Mutating nested state directly can silently skip re-renders because the object reference stays the same.',ARRAY['zustand','state','immutability']::text[],5),
('zustand','state','zustand-state-006','Replacing state entirely','set(newState, true)','Passing true as the second argument to set() replaces the whole state object instead of merging, removing any keys not present in the new object.','replace — set to true to disable the default shallow merge.',null,'set({ count: 0 }, true); // store state becomes exactly { count: 0 }','javascript','Use with care — any keys/actions not included in the replacement object are dropped from the store.',ARRAY['zustand','state','set']::text[],6),
('zustand','store','zustand-store-001','create()','import { create } from ''zustand''
const useStore = create((set, get) => ({ ... }))','Creates a Zustand store and returns a React hook used to read and subscribe to that store from any component.','stateCreatorFn — a function receiving (set, get, api) that returns the initial state object plus any actions.','A hook function (e.g. useStore) that components call to access the store''s state and actions.','const useCounterStore = create((set) => ({
  count: 0,
  increment: () => set((s) => ({ count: s.count + 1 })),
}));','javascript','create() lives outside React component code — typically in its own module — and the returned hook is imported wherever the store is needed.',ARRAY['zustand','store','create']::text[],1),
('zustand','store','zustand-store-002','Defining a store',null,'A Zustand store is a single object combining both state values and the actions that update them, defined once via create() and shared across the app.',null,null,'const useBearStore = create((set) => ({
  bears: 0,
  addBear: () => set((s) => ({ bears: s.bears + 1 })),
}));','javascript','Unlike Redux, there''s no separate reducer/action-type boilerplate — state and the logic that changes it live together in one function.',ARRAY['zustand','store','fundamentals']::text[],2),
('zustand','store','zustand-store-003','Store as a hook','const value = useStore((state) => state.value)','The value returned by create() is a standard React hook, so any component can call it directly to subscribe to store updates without wrapping it in a Provider.',null,'The selected piece of state (or the whole state object if no selector is passed).','function BearCounter() {
  const bears = useBearStore((state) => state.bears);
  return <h1>{bears} bears</h1>;
}','jsx','Calling the hook with no selector, e.g. useBearStore(), returns the entire state object and re-renders on any change.',ARRAY['zustand','store','hooks']::text[],3),
('zustand','store','zustand-store-004','No Provider needed',null,'Zustand stores are plain modules, not React context — there is no <Provider> to wrap the app in, and any component can import the hook and use it directly.',null,null,'// No <StoreProvider> wrapping required — just import and call the hook
import { useBearStore } from ''./store'';','javascript','This is a key differentiator from Redux (react-redux''s <Provider>) and React Context, which both require wrapping the component tree.',ARRAY['zustand','store','provider']::text[],4),
('zustand','store','zustand-store-005','Multiple stores',null,'Zustand encourages splitting state into several small, independent stores (e.g. useUserStore, useCartStore) rather than one large global store.',null,null,'const useUserStore = create((set) => ({ user: null }));
const useCartStore = create((set) => ({ items: [] }));','javascript','Multiple stores keep concerns isolated and avoid unrelated components re-rendering from unrelated state changes.',ARRAY['zustand','store','architecture']::text[],5),
('zustand','store','zustand-store-006','Store outside React','useStore.getState() / useStore.setState()','Every store created by create() exposes getState() and setState() directly on the hook, allowing state to be read or updated from outside React components (e.g. utility functions, event listeners).',null,'getState() returns the current state object; setState() applies a partial update.','// Outside any component
const bears = useBearStore.getState().bears;
useBearStore.setState({ bears: 0 });','javascript','Useful for non-React code such as API clients or analytics that need to read or update store state.',ARRAY['zustand','store','vanilla']::text[],6),
