('dom','events','dom-events-006','preventDefault()','event.preventDefault()','Cancels the browser''s default action for an event, such as following a link or submitting a form.',null,'undefined.','form.addEventListener(''submit'', (e) => e.preventDefault());','javascript','Only works if the event''s cancelable property is true; does not stop the event from propagating to other listeners.',ARRAY['dom','events']::text[],6),
