('dom','traversal','dom-traversal-007','childElementCount','parent.childElementCount','Returns the number of child elements a node has, ignoring text and comment nodes.',null,'A non-negative integer.','if (list.childElementCount === 0) showEmptyState();','javascript','Equivalent to but faster than element.children.length.',ARRAY['dom','traversal']::text[],7),
('dom','traversal','dom-traversal-008','querySelector() for descendant traversal','element.querySelector(selectors)','Scoping querySelector()/querySelectorAll() to a specific element restricts the search to its descendants, providing flexible downward traversal beyond direct children.',null,null,'card.querySelector(''.price'');','javascript',null,ARRAY['dom','traversal','css-selectors']::text[],8),
