('dom','traversal','dom-traversal-010','Node.ELEMENT_NODE vs nodeType','node.nodeType','Every node has a nodeType constant identifying what kind of node it is, such as 1 for elements (Node.ELEMENT_NODE) or 3 for text nodes (Node.TEXT_NODE), useful when filtering childNodes.',null,'An integer node type constant.','[...el.childNodes].filter(n => n.nodeType === Node.TEXT_NODE);','javascript',null,ARRAY['dom','traversal']::text[],10)
) as v(technology_slug, category_slug, slug, name, syntax, description, parameters, returns, example, code_language, notes, tags, display_order)
join public.cheatsheet_technologies t on t.slug = v.technology_slug
join public.cheatsheet_categories c on c.technology_id = t.id and c.slug = v.category_slug
on conflict (slug) do update set
  name = excluded.name,
  syntax = excluded.syntax,
  description = excluded.description,
  parameters = excluded.parameters,
  returns = excluded.returns,
  example = excluded.example,
  code_language = excluded.code_language,
  notes = excluded.notes,
  tags = excluded.tags,
  display_order = excluded.display_order,
  category_id = excluded.category_id,
  technology_id = excluded.technology_id;
